68	    private static final String DAG_VERSION = "DAG_VERSION";
69	    private static final ConcurrentHashMap<String, String> DAG_CACHE = new ConcurrentHashMap<>();
70	    // 当前java事例的版本号
71	    private final AtomicLong currentVersion = new AtomicLong(0);
72	    private final Object lock = new Object();
73	
