75	    public IndicatorDAG getIndicatorDAG() {
76	        // 获取redis中的版本号, 如果没有则初始化为1
77	        RAtomicLong redisVersion = redissonClient.getAtomicLong(DAG_VERSION);
78	        if (redisVersion.get() == 0L) {
79	            redisVersion.incrementAndGet();
80	        }
81	        IndicatorDAG res;
82	        String cacheString = DAG_CACHE.getOrDefault(IndicatorDAGKey, null);
83	        // 当前事例版本号小于redis中版本号, 直接重新构建
84	        if (currentVersion.get() == 0 || currentVersion.get() < redisVersion.get()) {
85	            cacheString = null;
86	        }
87	        if (cacheString == null) {
88	            synchronized (lock) {
89	                long currentVer = currentVersion.get();
90	                long totalVer = redisVersion.get();
91	                if (currentVer == 0 || currentVer < totalVer) {
92	                    LOGGER.info("DAG缓存重新构建, 当前版本: {}, 远端版本: {}", currentVer, totalVer);
93	                    rebuild();
94	                    currentVersion.set(totalVer);
95	                }
96	            }
97	        }
98	
99	        // 使用json深拷贝, 防止谁不小心修改了DAG, 导致全部线程都有问题
100	        res = JsonUtil.jsonStr2Obj(DAG_CACHE.get(IndicatorDAGKey), IndicatorDAG.class);
101	        res.setEdgeMap(new HashMap<>());
102	        res.setNodeMap(res.getEventNodes().stream()
103	                .collect(Collectors.toMap(EventNode::getCode, e -> e)));
104	
105	        // 因为深拷贝的原因, 引用类数据需要重新赋值
106	        // 初始化edgeMap
107	        for (EdgeRule edgeRule : res.getEdgeRules()) {
108	            for (String codeFrom : edgeRule.getCodeFrom()) {
109	                String codeTo = edgeRule.getCodeTo();
110	                EventNode nodeFrom = res.getNodeMap().get(codeFrom);
111	                EventNode nodeTo = res.getNodeMap().get(codeTo);
112	                if (nodeFrom == null || nodeTo == null) {
113	                    LOGGER.info("DAG中未找到对应的节点, codeFrom: {}, codeTo: {}", codeFrom, codeTo);
114	                    continue;
115	                }
116	                String edgeKey = codeFrom + "," + codeTo;
117	                if (!res.getEdgeMap().containsKey(edgeKey)) {
118	                    NodeEdge nodeEdge = NodeEdge.builder()
119	                            .nodeFrom(nodeFrom)
120	                            .nodeTo(nodeTo)
121	                            .ruleList(new ArrayList<>())
122	                            .build();
123	                    res.getEdgeMap().put(edgeKey, nodeEdge);
124	
125	                    nodeFrom.getEdgeOutList().add(nodeEdge);
126	                    nodeTo.getEdgeInList().add(nodeEdge);
127	                }
128	                res.getEdgeMap().get(edgeKey).getRuleList().add(edgeRule);
129	
130	
131	                // 当codeTo为最后通知送货时, 配置中的首次通知送货也要延续计算
132	                // otherNodeTo 不一定存在
133	                String otherCodeTo = codeTo.replace("l_", "f_");
134	                EventNode otherNodeTo = res.getNodeMap().get(otherCodeTo);
135	                if (otherNodeTo == null) {
136	                    continue;
137	                }
138	                edgeKey = codeFrom + "," + otherCodeTo;
139	                if (!res.getEdgeMap().containsKey(edgeKey)) {
140	                    NodeEdge nodeEdge = NodeEdge.builder()
141	                            .nodeFrom(nodeFrom)
142	                            .nodeTo(otherNodeTo)
143	                            .ruleList(new ArrayList<>())
144	                            .build();
145	                    res.getEdgeMap().put(edgeKey, nodeEdge);
146	
147	                    nodeFrom.getEdgeOutList().add(nodeEdge);
148	                    otherNodeTo.getEdgeInList().add(nodeEdge);
149	                }
150	                res.getEdgeMap().get(edgeKey).getRuleList().add(edgeRule);
151	
152	            }
153	        }
154	
155	        // 初始化nodeMap, 将入度出度为0的节点过滤掉
156	        res.setEventNodes(res.getEventNodes().stream()
157	                .filter(en -> !(en.getEdgeOutList().isEmpty() && en.getEdgeInList().isEmpty()))
158	                .collect(Collectors.toList()));
159	        res.setNodeMap(res.getEventNodes().stream()
160	                .collect(Collectors.toMap(EventNode::getCode, e -> e)));
161	        LOGGER.info("获取DAG成功, eventNodes: {}, edgeRules: {}", res.getEventNodes().size(), res.getEdgeRules().size());
162	        return res;
163	    }
