171	        LOGGER.info("rebuild数据准备完成");
172	
173	        List<EventNode> eventNodes = new ArrayList<>();
174	        List<EdgeRule> edgeRules = new ArrayList<>();
175	
176	        for (IndicatorEvent event : allEvents) {
177	            EventNode eventNode = EventNode.builder()
178	                    .code(event.getCode())
179	                    .categoryId(event.getCategoryId())
180	                    .name(event.getEventName())
181	                    .eventType(event.getEventType())
182	                    .timeType(event.getTimeType())
183	                    .taskInfo(event.getTaskInfo())
184	                    .edgeInList(new ArrayList<>())
185	                    .edgeOutList(new ArrayList<>())
186	                    .pre("l")
187	                    .ofcCode(event.getCode())
188	                    .build();
189	            if (!EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue().equals(event.getEventType())) {
190	                String[] subs = event.getCode().split("_");
191	                if (subs.length >= 3) {
192	                    eventNode.setOfcCode(subs[2]);
193	                    eventNode.setPre(subs[0]);
194	                }
