206	                continue;
207	            }
208	            List<DeliveryInfo> deliveryInfos = JsonUtil.jsonStr2Obj(rule.getDeliveryInfo(), new TypeReference<List<DeliveryInfo>>() {});
209	            Set<String> deliveryIdSet = deliveryInfos.stream()
210	                    .map(DeliveryInfo::getDeliveryId)
211	                    .collect(Collectors.toSet());
212	            String deliveryIds = String.join(",", deliveryIdSet);
213	            int index = 0;
214	            for (TimeRule r : funcTimeRule.getTimeRuleList()) {
215	                EdgeRule edgeRule = EdgeRule.builder()
216	                        .ruleId(rule.getId())
217	                        .indexId(index)
218	                        .sourceId(rule.getSourceId())
219	                        .sourceType(rule.getSourceType())
220	                        .secondType(rule.getSecondType())
221	                        .mainType(rule.getMainType())
222	                        .businessType(rule.getBusinessType())
223	                        .businessVersion(rule.getBusinessVersion())
224	                        .indicatorName(rule.getIndicatorName())
225	                        .configType(rule.getConfigType())
226	                        .assessmentRole(rule.getAssessmentRole())
227	                        .indicatorNode(rule.getIndicatorNode())
228	                        .categoryId(rule.getCategoryId())
229	                        .categoryName(rule.getCategoryName())
230	                        .funcName(funcTimeRule.getFuncName())
231	                        .deliveryIds(deliveryIds)
232	                        .deliveryIdSet(deliveryIdSet)
233	                        .deliveryType(rule.getDeliveryType())
234	                        .hasMeasurementNode(rule.getHasMeasurementNode())
235	                        .hasDeliveryNotificationNode(rule.getHasDeliveryNotificationNode())
236	                        .version(rule.getVersion())
237	                        .startTime(rule.getStartTime())
238	                        .endTime(rule.getEndTime())
239	                        .codeFrom(r.getNodeFrom())
240	                        .codeTo(r.getNodeTo())
241	                        .timeType(r.getTimeType())
242	                        .timeRef(r.getTimeRef())
243	                        .interval(r.getInterval())
244	                        .cusConfig(cusMap.getOrDefault(rule.getSourceId(), null))
245	                        .build();
246	                if (edgeRule.getCodeTo().startsWith("F")) {
247	                    edgeRule.setCodeTo(edgeRule.getCodeTo().substring(1));
248	                }
249	                edgeRule.setCodeTo(String.format("l_%s_%s", edgeRule.getCategoryId(), edgeRule.getCodeTo()));
250	                edgeRules.add(edgeRule);
251	                index += 1;
252	            }
253	        }
254	
255	        LOGGER.info("rebuild数据拼装完成, eventNodes: {}, edgeRules: {}", eventNodes.size(), edgeRules.size());
256	        IndicatorDAG res = IndicatorDAG.builder()
257	            .eventNodes(eventNodes)
258	            .edgeRules(edgeRules)
259	            .build();
260	
261	        DAG_CACHE.put(IndicatorDAGKey, JsonUtil.obj2JsonStr(res));
262	    }
