264	    public List<EventNode> getFigureNodeList(List<EventNode> startNodes, List<EventNode> extNodes, Map<String, List<IndicatorOrder>> orderMap,
265	                                             Map<String, List<IndicatorProjectOrder>> projectOrderMap) {
266	        // startNodes 支持多个起始点
267	        // extNode 支持额外的节点, 直接追加到dfs结果的后面(如果dfs结果中不包含的话)
268	        // 获取全部需要计算考核时间的node
269	        List<EventNode> res = new ArrayList<>();
270	        for (EventNode startNode : startNodes) {
271	            Set<String> edgeVisited = new HashSet<>();
272	            Set<String> nodeVisited = new HashSet<>();
273	            List<EventNode> figureNodeList = new ArrayList<>();
274	            dfs(startNode, orderMap, projectOrderMap, edgeVisited, nodeVisited, figureNodeList);
275	            res.addAll(figureNodeList);
276	            // extNode 使用nodeVisited过滤
277	            extNodes = extNodes.stream()
278	                    .filter(ext -> !nodeVisited.contains(ext.getCode()))
279	                    .collect(Collectors.toList());
280	        }
281	        res.addAll(extNodes);
282	        return distinctNodes(res);
283	    }
