285	    private List<EventNode> distinctNodes(List<EventNode> nodeList) {
286	        // 去重, 保留靠后出现的元素
287	        Collections.reverse(nodeList);
288	        nodeList = nodeList.stream().distinct().collect(Collectors.toList());
289	        Collections.reverse(nodeList);
290	        return nodeList;
291	    }
