293	    private void dfs(EventNode node, Map<String, List<IndicatorOrder>> orderMap,
294	                     Map<String, List<IndicatorProjectOrder>> projectOrderMap,
295	                     Set<String> edgeVisited, Set<String> nodeVisited,
296	                     List<EventNode> figureNodeList) {
297	        // edgeVisited 用于记录哪些边已经访问过, 防止重复访问
298	        // nodeVisited 用于记录哪些节点已经访问过, 可以重复访问
299	        if (CollectionUtils.isEmpty(node.getEdgeOutList())) {
300	            return;
301	        }
302	        for (NodeEdge edge : node.getEdgeOutList()) {
303	            EventNode nextNode = edge.getNodeTo();
304	            String edgeKey = node.getCode() + "__" + nextNode.getCode();
305	            String nodeKey = nextNode.getCode();
306	            if (edgeVisited.contains(edgeKey)) {
307	                // 已沿当前路径访问过, 不用再访问了
308	                continue;
309	            }
310	            edgeVisited.add(edgeKey);
311	            nodeVisited.add(nodeKey);
312	
313	            // 尝试按照orderNo过滤数据, 注意不要修改orderMap
314	            List<IndicatorOrder> orders = new ArrayList<>(orderMap.getOrDefault(nextNode.getCategoryId(), new ArrayList<>()));
315	
316	            // 如果是下单节点, 需要特殊处理, 使用projectOrder
317	            List<IndicatorProjectOrder> projectOrders = nextNode.getName().equals("下单") ? projectOrderMap.getOrDefault(nextNode.getCategoryId(), new ArrayList<>()) : new ArrayList<>();
318	
319	            if (!hasFilterRules(edge.getRuleList(), orders, projectOrders)) {
320	                // 没有合适的规则, 不用继续遍历
321	                continue;
322	            }
323	            figureNodeList.add(nextNode);
324	            dfs(nextNode, orderMap, projectOrderMap, edgeVisited, nodeVisited, figureNodeList);
325	        }
326	    }
