328		public Map<Integer, List<ExtendedEdgeRule>> filterExtendedEdgeRules(List<ExtendedEdgeRule> rules,
329	                                                                        IndicatorOrder order, IndicatorProjectOrder projectOrder) {
330			Map<Integer, List<ExtendedEdgeRule>> result = new HashMap<>();
331	
332			boolean hasOrder = order != null;
333			boolean hasProjectOrder = projectOrder != null;
334	        IndicatorOrderBO orderBO = hasOrder ? indicatorOrderServiceImpl.convert(order) : null;
335	        IndicatorProjectOrderBo projectOrderBo = hasProjectOrder ? indicatorProjectOrderService.convertToBo(projectOrder) : null;
336	
337	        // 按照订单信息过滤数据
338			for (int sourceType : Arrays.asList(0, 1)) {
339	            List<ExtendedEdgeRule> filteredRules = rules.stream()
340	                    .filter(rule -> rule.getSourceType() == sourceType)
341	                    .filter(rule -> {
342	                        if (hasOrder) {
343	                            return rule.getSecondType().equals(order.getSecondType())
344	                                    && rule.getBusinessType().equals(order.getBusinessType())
345	                                    && rule.getBusinessVersion().equals(order.getBusinessVersion())
346	                                    && rule.getCategoryId().equals(order.getCategoryId())
347	                                    && (rule.getDeliveryType() == -99 || rule.getDeliveryType().equals(order.getDeliveryType().intValue()))
348	                                    && (rule.getHasMeasurementNode() == -1 || rule.getHasMeasurementNode().equals(order.getNeedMeasure().intValue()))
349	                                    && (rule.getHasDeliveryNotificationNode() == -1 || rule.getHasDeliveryNotificationNode().equals(order.getHasDeliveryTask().intValue()))
350	                                    && (rule.getDeliveryIdSet().contains(ComplexQueryRpc.DEFAULT_DELIVERY_INFO.getDeliveryId()) || rule.getDeliveryIdSet().contains(order.getSupplierId()));
351	                        }
352	
353	                        if (hasProjectOrder) {
354	                            boolean matchesBusinessType;
355	                            if (projectOrder.getGroupDecoration() == 1) {
356	                                // 如果是团装, 只匹配团装业务类型
357	                                matchesBusinessType = rule.getBusinessType().equals(BusinessType.GROUP.getType());
358	                            } else if (projectOrder.getPartialDecoration() == 1) {
359	                                // 如果是局装, 只匹配局装业务类型
360								    matchesBusinessType = rule.getBusinessType().equals(BusinessType.PARTIAL_DECORATION.getType());
361	                            } else {
362	                                // 如果是其他业务类型, 不匹配团装和局装
363	                                matchesBusinessType = !rule.getBusinessType().equals(BusinessType.GROUP.getType())
364	                                        && !rule.getBusinessType().equals(BusinessType.PARTIAL_DECORATION.getType());
365	                            }
366	                            return rule.getCategoryId().equals(projectOrder.getCategoryId())
367	                                    && (rule.getDeliveryType() == -99 || rule.getDeliveryType().equals(projectOrder.getDeliveryType().intValue()))
368	                                    && (rule.getHasMeasurementNode() == -1 || rule.getHasMeasurementNode().equals(projectOrder.getNeedMeasure().intValue()))
369	                                    && (rule.getHasDeliveryNotificationNode() == -1 || rule.getHasDeliveryNotificationNode().equals(projectOrder.getHasDeliveryTask().intValue()))
370	                                    && matchesBusinessType
371	                                    && !DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(rule.getSecondType())
372	                                    && (rule.getDeliveryIdSet().contains(ComplexQueryRpc.DEFAULT_DELIVERY_INFO.getDeliveryId()) || rule.getDeliveryIdSet().contains(projectOrder.getDeliveryId()));
373	                        }
374	                        return false;
375	                    })
376	                    .collect(Collectors.toList());
377	            result.put(sourceType, filteredRules);
378			}
379	
380	        // 城市考核规则需要按照城市过滤
381	        List<ExtendedEdgeRule> cusRules = Optional.ofNullable(result.get(1).stream()
382	                .filter(rule -> {
383	                    if (hasOrder) {
384	                        return EvalOrderService.qvyuPredicate.or(EvalOrderService.BranchPredicate).or(EvalOrderService.merchantPredicate).test(orderBO, rule.getCusConfig());
385	                    }
386	                    if (hasProjectOrder) {
387	                        return EvalOrderService.qvyuProjectPredicate.or(EvalOrderService.BranchProjectPredicate).test(projectOrderBo, rule.getCusConfig());
388	                    }
389	                    return false;
390	                })
391	                .collect(Collectors.groupingBy(
392	                        (o -> o.getCusConfig().getGranularityType()), TreeMap::new, Collectors.toList()
393	                )).lastEntry())
394	                .map(Map.Entry::getValue)
395	                .orElse(Collections.emptyList());
396	        result.put(1, cusRules);
397			return result;
398		}
