400		private Boolean hasFilterRules(List<EdgeRule> rules, List<IndicatorOrder> orders, List<IndicatorProjectOrder> projectOrders) {
401			for (IndicatorOrder order : orders) {
402	            for (EdgeRule rule : rules) {
403	                if (rule.getSecondType().equals(order.getSecondType())
404	                        && rule.getBusinessType().equals(order.getBusinessType())
405	                        && rule.getBusinessVersion().equals(order.getBusinessVersion())
406	                        && rule.getCategoryId().equals(order.getCategoryId())
407	                        && (rule.getDeliveryType().equals(-99) || rule.getDeliveryType().equals(order.getDeliveryType().intValue()))
408	                        && (rule.getHasMeasurementNode().equals(-1) || rule.getHasMeasurementNode().equals(order.getNeedMeasure().intValue()))
409	                        && (rule.getHasDeliveryNotificationNode().equals(-1) || rule.getHasDeliveryNotificationNode().equals(order.getHasDeliveryTask().intValue()))) {
410	                    return true;
411	                }
412	            }
413			}
414			for (IndicatorProjectOrder projectOrder : projectOrders) {
415	            for (EdgeRule rule : rules) {
416	                if (rule.getCategoryId().equals(projectOrder.getCategoryId())
417	                        && (rule.getDeliveryType().equals(-99) || rule.getDeliveryType().equals(projectOrder.getDeliveryType().intValue()))
418	                        && (rule.getHasMeasurementNode().equals(-1) || rule.getHasMeasurementNode().equals(projectOrder.getNeedMeasure().intValue()))
419	                        && (rule.getHasDeliveryNotificationNode().equals(-1) || rule.getHasDeliveryNotificationNode().equals(projectOrder.getHasDeliveryTask().intValue()))) {
420	                    if (projectOrder.getGroupDecoration().equals(1) && !rule.getBusinessType().equals(BusinessType.GROUP.getType())) {
421	                        continue;
422	                    }
423	                    if (projectOrder.getPartialDecoration().equals(1) && !rule.getBusinessType().equals(BusinessType.PARTIAL_DECORATION.getType())) {
424	                        continue;
425	                    }
426	                    return true;
427	                }
428	            }
429			}
430			return false;
431		}
