434	                                           Map<String, List<IndicatorProjectOrder>> projectOrderMap) {
435	        // 获取全部需要拉取轨迹的node
436	        Set<EventNode> dataNodeSet = new HashSet<>();
437	        for (EventNode node : fugureNodeList) {
438	
439	            // 尝试按照orderNo过滤数据, 注意不要修改orderMap
440	            List<IndicatorOrder> orders = new ArrayList<>(orderMap.getOrDefault(node.getCategoryId(), new ArrayList<>()));
