443	            List<IndicatorProjectOrder> projectOrders = node.getName().equals("下单") ? projectOrderMap.getOrDefault(node.getCategoryId(), new ArrayList<>()) : new ArrayList<>();
444	
445	            for (NodeEdge edge : node.getEdgeInList()) {
446	                if (hasFilterRules(edge.getRuleList(), orders, projectOrders)) {
447	                    dataNodeSet.add(edge.getNodeFrom());
448	                    // 验证通过的话, figureNode自身也需要获取时间
449	                    // 因为实际完成时间需要写到考核结果中
450	                    dataNodeSet.add(node);
451	                }
452	            }
453	        }
454	        return new ArrayList<>(dataNodeSet);
