538	    public FigureParam filterEventNodes(String projectOrderId, Integer actionType, String categoryId) {
539	        IndicatorDAG indicatorDAG = getIndicatorDAG();
540	        if (Objects.isNull(indicatorDAG) || CollectionUtils.isEmpty(indicatorDAG.getEventNodes())) {
541	            return null;
542	        }
543	
544	        List<EventNode> eventNodeList = indicatorDAG.getEventNodes();
545	
546	        // 查询直接命中的事件, 作为startNode(dfs的起点)
547	        List<String> targetEvent = Arrays.asList(
548	                String.format("l_%s_%s", categoryId, actionType),
549	                String.format("f_%s_%s", categoryId, actionType)
550	        );
551	
552	        // 查询货单扩展事件, 也进行计算
553	        // 用额外的数据计算, 保证准确性, 防止计算失败而导致的某些节点永远不再计算
554	        Set<String> extEventSet = OfcFulfillmentEventHandler.ORDER_ACTION_TYPE_LIST.stream()
555	                .map(eventType -> String.format("l_%s_%s", categoryId, eventType))
556	                .collect(Collectors.toSet());
557	
558	        List<EventNode> starts = eventNodeList.stream()
559	                .filter(e -> targetEvent.contains(e.getCode()))
560	                .collect(Collectors.toList());
561	
562	        List<EventNode> extNodes = eventNodeList.stream()
563	                .filter(e -> extEventSet.contains(e.getCode()))
564	                .collect(Collectors.toList());
565	
566	        return FigureParam.builder()
567	                .projectOrderNo(projectOrderId)
568	                .startNodes(starts)
569	                .extNodes(extNodes)
570	                .build();
571	    }
