129	    public void calculateScheduleIndicatorByEvents(String projectOrderId, List<ScheduleEventNode> startNodes,
130	                                                   List<ScheduleEventNode> extNodes, Boolean syncMaterialTask) {
131	
132	        // 初始化任务载体
133	        ScheduleAllNode scheduleAllNode = ScheduleAllNode.builder()
134	                .projectOrderId(projectOrderId)
135	                .orderNodeMap(new HashMap<>())
136	                .dispatchNodeMap(new HashMap<>())
137	                .orderMap(new HashMap<>())
138	                .projectOrderMap(new HashMap<>())
139	                .build();
140	
141	        // 获取待计算节点
142	        List<ScheduleEventNode> figureNodeList = indicatorScheduleDAGService.getFigureNodeList(startNodes, scheduleAllNode);
143	
144	        // 额外计算节点
145	        if (extNodes != null && !extNodes.isEmpty()) {
146	            Set<String> exists = figureNodeList.stream()
147	                    .map(ScheduleEventNode::getUniqCode)
148	                    .collect(Collectors.toSet());
149	            for (ScheduleEventNode extNode : extNodes) {
150	                if (!exists.contains(extNode.getUniqCode())) {
151	                    figureNodeList.add(extNode);
152	                }
153	            }
154	        }
155	        LOGGER.info("calculateScheduleIndicatorByEvents，获取计算节点:{}", JsonUtil.obj2JsonStr(figureNodeList.stream()
156	                .map(ScheduleEventNode::getUniqCode)
157	                .collect(Collectors.toList())));
158	
159	        // 获取数据节点
160	        List<ScheduleEventNode> dataNodeList = indicatorScheduleDAGService.getDataNodeList(figureNodeList, scheduleAllNode);
161	        LOGGER.info("calculateScheduleIndicatorByEvents，获取数据节点:{}", JsonUtil.obj2JsonStr(dataNodeList.stream()
162	                .map(ScheduleEventNode::getUniqCode)
163	                .collect(Collectors.toList())));
164	
165	        // 基于数据节点, 获取轨迹
166	        List<NodeTimeTrackV2> nodeTrackList = getScheduleTimeTrack(projectOrderId, scheduleAllNode, dataNodeList);
167	
168	        // 数据都准备好了, 开始算数吧
169	        doScheduleEval(figureNodeList, nodeTrackList, scheduleAllNode, syncMaterialTask);
170	    }
