172	    public void doScheduleEval(List<ScheduleEventNode> figureNodeList, List<NodeTimeTrackV2> nodeTrackList,
173	                               ScheduleAllNode scheduleAllNode, Boolean syncMaterialTask) {
174	        Map<String, NodeTimeTrackV2> nodeTimeTrackMap = nodeTrackList.stream()
175	                .collect(Collectors.toMap(NodeTimeTrackV2::getCode, Function.identity(), (v1, v2) -> v1));
176	
177	        Map<LocalDateTime, Integer> calendars = holidayService.getRecentCalendar();
178	
179	        for (ScheduleEventNode figureNode : figureNodeList) {
180	            List<ScheduleEdgeRule> ruleList = flatRules(figureNode.getEdgeInList());
181	            LOGGER.info("doScheduleEval打平后的粗过滤规则, eventNode: {}, ruleList: {}", figureNode.getUniqCode(), JsonUtil.obj2JsonStr(ruleList));
182	
183	            // 判断挂载的任务载体
184	            if (!IndicatorScheduleDAGService.EVENT_ENTITY.containsKey(figureNode.getName())) {
185	                continue;
186	            }
187	            String categoryId = figureNode.getCategoryId();
188	            List<Integer> entityInfo = IndicatorScheduleDAGService.EVENT_ENTITY.get(figureNode.getName());
189	            Integer entityType = entityInfo.get(0);
190	            Integer taskType = entityInfo.get(1);
191	
192	            // 货单节点的考核计算
193	            if (entityType.equals(IndicatorScheduleDAGService.ORDER_NODE)) {
194	                for (ScheduleOrderNode orderNode : scheduleAllNode.getOrderNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
195	                    dealOrderNode(ruleList, orderNode, nodeTimeTrackMap, figureNode, calendars, scheduleAllNode, syncMaterialTask);
196	                }
197	            }
198	
199	            // 用工节点的考核计算
200	            if (entityType.equals(IndicatorScheduleDAGService.DISPATCH_NODE)) {
201	                for (ScheduleDispatchNode dispatchNode : scheduleAllNode.getDispatchNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
202	                    Integer nodeType = entityInfo.get(2);
203	                    if (nodeType.equals(dispatchNode.getNodeType())) {
204	                        dealDispatchNode(ruleList, dispatchNode, nodeTimeTrackMap, figureNode, calendars, scheduleAllNode, syncMaterialTask);
205	                    }
206	                }
207	            }
208	        }
209	    }
