211	    private void dealOrderNode(List<ScheduleEdgeRule> ruleList, ScheduleOrderNode orderNode, Map<String, NodeTimeTrackV2> nodeTimeTrackMap,
212	                               ScheduleEventNode figureNode, Map<LocalDateTime, Integer> calendars,
213	                               ScheduleAllNode scheduleAllNode, Boolean syncMaterialTask) {
214	        FigureRes figureRes = figureNode(ruleList, orderNode, null, figureNode, nodeTimeTrackMap, calendars);
215	        if (figureRes.getFigureTime() == null) {
216	            return;
217	        }
218	        if (orderNode.getReplacement()) {
219	            adjustExpectTimeForReplacement(orderNode.getReplaceDate(), figureRes.getFigureTime(), calendars);
220	            syncBaseEvalResult(figureRes);
221	        }
222	        // 更新轨迹中的考核时间（汰换调整后执行，确保写入最终考核时间）
223	        updateAssessmentTimeInTrack(nodeTimeTrackMap.getOrDefault(figureNode.getUniqCode(), null),
224	                figureRes.getFigureTime(), orderNode, null);
225	
226	        boolean update = false;
227	
228	        // 下单考核时间的处理, 下单考核时间在indicator_project_order
229	        if (FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode().equals(orderNode.getTaskType())) {
230	            IndicatorProjectOrder projectOrder = scheduleAllNode.getProjectOrderMap().get(orderNode.getId());
231	            List<IndicatorEvalSDO> baseEvalSDOS = evalOrderService.mergeIndicator(
232	                    Optional.ofNullable(JSONArray.parseArray(projectOrder.getBaseEvalResult(), IndicatorEvalSDO.class)).orElse(new ArrayList<>()),
233	                    figureRes.getBaseEvalResult()
234	            );
235	
236	            updateProjectOrder(projectOrder, baseEvalSDOS);
237	            update = updateFulfillmentTask(null, projectOrder.getProjectOrderId(), projectOrder.getCategoryId(),
238	                    projectOrder.getDeliveryId(), figureRes.getFigureTime(),
239	                    FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode(), false);
240	            updateIndicatorOrder(projectOrder, figureRes.getBaseEvalResult(), scheduleAllNode);
241	        }
242	
243	        if (!FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode().equals(orderNode.getTaskType())) {
244	            IndicatorOrder order = scheduleAllNode.getOrderMap().get(orderNode.getId());
245	            List<IndicatorEvalSDO> baseEvalSDOS = evalOrderService.mergeIndicator(
246	                    Optional.ofNullable(JSONArray.parseArray(order.getBaseEvalResult(), IndicatorEvalSDO.class)).orElse(new ArrayList<>()),
247	                    figureRes.getBaseEvalResult()
248	            );
249	            updateOrder(order, baseEvalSDOS);
250	            update = updateFulfillmentTask(order.getOrderNo(), order.getProjectOrderId(), order.getCategoryId(), orderNode.getFulfillmentDeliveryId(),
251	                    figureRes.getFigureTime(), orderNode.getTaskType(), DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()));
252	            if (update && syncMaterialTask && FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode().equals(orderNode.getTaskType())) {
253	                // 送达考核时间需要同步供应商
254	                IndicatorChangedEvent indicatorChangedEvent = IndicatorChangedEvent.builder()
255	                        .orderNo(order.getOrderNo())
256	                        .projectOrderId(Long.valueOf(order.getProjectOrderId()))
257	                        .branchCode(order.getBranchCode())
258	                        .baseEval(baseEvalSDOS)
259	                        .updatedEval(new HashSet<>(Collections.singletonList(ScheduleEventNameEnum.DELIVERY_GOODS.getName())))
260	                        .orderCreateTime(order.getCtime())
261	                        .qvyu(order.getQvyv())
262	                        .categoryId(order.getCategoryId())
263	                        .deliveryId(order.getDeliveryId())
264	                        .flowType(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()) ?
265	                                FlowTypeEnum.REVERSE_ORDER.getCode() : FlowTypeEnum.NORMAL_ORDER.getCode())
266	                        .taskMode(TaskModeEnum.SCHEDULE.getTaskMode())
267	                        .build();
268	                applicationEventPublisher.publishEvent(indicatorChangedEvent);
269	            }
270	        }
271	
272	        if (update) {
273	            // 同步考核时间到主材任务
274	            if (syncMaterialTask) {
275	                rpcAsyncExecutor.execute(() -> {
276	                    syncMaterialTaskService.syncAssessmentTime(orderNode, null, figureRes.getFigureTime().getExpectTime());
277	                });
278	            }
279	        }
280	        // 同步考核时间到排程
281	        sendAssessmentMessage(orderNode, null, figureRes.getFigureTime().getExpectStartTime(), figureRes.getFigureTime().getExpectTime());
282	
283	    }
