285	    private void dealDispatchNode(List<ScheduleEdgeRule> ruleList, ScheduleDispatchNode dispatchNode, Map<String, NodeTimeTrackV2> nodeTimeTrackMap,
286	                                  ScheduleEventNode figureNode, Map<LocalDateTime, Integer> calendars,
287	                                  ScheduleAllNode scheduleAllNode, Boolean syncMaterialTask) {
288	        FigureRes figureRes = figureNode(ruleList, null, dispatchNode, figureNode, nodeTimeTrackMap, calendars);
289	        if (figureRes.getFigureTime() == null) {
290	            return;
291	        }
292	        if (dispatchNode.getReplacement()) {
293	            adjustExpectTimeForReplacement(dispatchNode.getReplaceDate(), figureRes.getFigureTime(), calendars);
294	            syncBaseEvalResult(figureRes);
295	        }
296	        // 更新轨迹中的考核时间（汰换调整后执行，确保写入最终考核时间）
297	        updateAssessmentTimeInTrack(nodeTimeTrackMap.getOrDefault(figureNode.getUniqCode(), null),
298	                figureRes.getFigureTime(), null, dispatchNode);
299	
300	        boolean update = updateDispatch(dispatchNode, figureRes);
301	        if (update) {
302	            // 同步考核时间到主材任务
303	            // mode = 7的全部同步（有一些未进排程的历史项目存在mode = 7的脏数据, 这些数据需要在这里同步）
304	            if (syncMaterialTask || ModeEnum.DELIVERY_FLOW.getValue().equals(dispatchNode.getMode())) {
305	                rpcAsyncExecutor.execute(() -> {
306	                    syncMaterialTaskService.syncAssessmentTime(null, dispatchNode, figureRes.getFigureTime().getExpectTime());
307	                });
308	            }
309	        }
310	        // 同步考核时间到排程
311	        sendAssessmentMessage(null, dispatchNode, figureRes.getFigureTime().getExpectStartTime(), figureRes.getFigureTime().getExpectTime());
312	    }
