314	    /**
315	     * 汰换节点：考核时间取 max(计算考核时间, 汰换时间 + N自然日)
316	     * N 由 Apollo 配置 replace_supplier_assessment_buffer_days 控制，默认为 3
317	     * 若触发调整，同步更新 expectStartTime 为汰换时间
318	     */
319	    private void adjustExpectTimeForReplacement(Date replaceDate, CalculatedTimeline figureTime, Map<LocalDateTime, Integer> calendars) {
320	        if (replaceDate == null || figureTime == null || figureTime.getExpectTime() == null) {
321	            return;
322	        }
323	        Date replaceAssessmentTime = DateUtil.localDateTime2Date(RuleUnit.figureAssessmentTime(
324	                DateUtil.date2LocalDateTime(replaceDate), apolloConfig.getReplaceBufferDays(), HolidayService.CALENDAR_DAY_BITMASK, calendars));
325	        if (replaceAssessmentTime.after(figureTime.getExpectTime())) {
326	            figureTime.setExpectStartTime(replaceAssessmentTime);
327	            figureTime.setExpectTime(replaceAssessmentTime);
328	        }
329	    }
