343	                && DateUtil.string2Date(evalSDO.getRealCompTime()).after(DateUtil.string2Date(evalSDO.getExpectCompTime()))) {
344	            evalSDO.setEvaluation(1);
345	        } else {
346	            evalSDO.setEvaluation(0);
347	        }
348	    }
