350	    private FigureRes figureNode(List<ScheduleEdgeRule> ruleList, ScheduleOrderNode orderNode, ScheduleDispatchNode dispatchNode, ScheduleEventNode figureNode,
351	                                 Map<String, NodeTimeTrackV2> nodeTimeTrackMap, Map<LocalDateTime, Integer> calendars) {
352	        FigureRes res = new FigureRes();
353	        List<ScheduleEdgeRule> orderRules = filterRuleByOrderNode(ruleList, orderNode, dispatchNode);
354	        LOGGER.info("figureOrderNode细过滤规则: figureNode: {}, orderNode: {}, dispatchNode: {}, orderRules: {}",
355	                figureNode.getUniqCode(), JsonUtil.obj2JsonStr(orderNode), JsonUtil.obj2JsonStr(dispatchNode), JsonUtil.obj2JsonStr(orderRules));
356	        if (orderRules.isEmpty()) {
357	            return res;
358	        }
359	
360	        CalculatedTimeline evalTime = figureCore(orderRules, nodeTimeTrackMap, orderNode, dispatchNode, figureNode, calendars);
361	        LOGGER.info("figureOrderNode计算结果: orderNode:{}, dispatchNode:{}, evalTime: {}", JsonUtil.obj2JsonStr(orderNode), JsonUtil.obj2JsonStr(dispatchNode), JsonUtil.obj2JsonStr(evalTime));
362	        if (evalTime == null) {
363	            return res;
364	        }
365	
366	        // 考核结果转为固定结构体
367	        IndicatorEvalSDO evalResult = createIndicatorEvalSDO(evalTime, nodeTimeTrackMap, figureNode, orderNode, dispatchNode);
368	
369	        return FigureRes.builder()
370	                .baseEvalResult(evalResult)
371	                .figureTime(evalTime)
372	                .build();
373	    }
