375	    private CalculatedTimeline figureCore(List<ScheduleEdgeRule> rules, Map<String, NodeTimeTrackV2> nodeTimeTrackMap,
376	                                          ScheduleOrderNode orderNode, ScheduleDispatchNode dispatchNode, ScheduleEventNode figureNode,
377	                                          Map<LocalDateTime, Integer> calendars) {
378	        if (orderNode == null && dispatchNode == null) {
379	            return null;
380	        }
381	        List<CalculatedTimeline> calculatedTimelines = new ArrayList<>();
382	
383	        // ruleId = 品类 + 供应商 + 履约方式 + 任务类型 + 是否重启(是否返补)
384	        // 除供应商/履约方式外(不限制时为-1), 其余字段皆在细过滤中精准匹配
385	        List<List<ScheduleEdgeRule>> sortedGroups = rules.stream()
386	                .collect(Collectors.groupingBy(ScheduleEdgeRule::getRuleId))
387	                .values()
388	                .stream()
389	                .sorted(Comparator.comparing((List<ScheduleEdgeRule> group) -> group.get(0).getDeliveryType(), Comparator.nullsLast(Comparator.reverseOrder()))
390	                        .thenComparing(group -> group.get(0).getDeliveryId(), Comparator.nullsLast(Comparator.reverseOrder()))
391	                )
392	                .collect(Collectors.toList());
393	        LOGGER.info("figureCore分组规则, 按ruleId分组，配送不限制靠后，供应商不限制靠后: figureNode: {}, orderNode: {}, dispatchNode: {}, sortedGroups: {}",
394	                figureNode.getUniqCode(), JsonUtil.obj2JsonStr(orderNode), JsonUtil.obj2JsonStr(dispatchNode), JsonUtil.obj2JsonStr(sortedGroups));
395	
396	        if (sortedGroups.isEmpty()) {
397	            return null;
398	        }
399	
400	        // 只取第一组符合条件的考核规则
401	        List<ScheduleEdgeRule> usedRules = sortedGroups.get(0);
402	        if (CollectionUtils.isEmpty(usedRules)) {
403	            return null;
404	        }
405	        String funcName = usedRules.get(0).getFuncName();
406	        Map<Integer, List<ScheduleEdgeRule>> ruleMap = usedRules.stream()
407	                .collect(Collectors.groupingBy(ScheduleEdgeRule::getIndexId));
408	        for (Map.Entry<Integer, List<ScheduleEdgeRule>> entry : ruleMap.entrySet()) {
409	            List<ScheduleEdgeRule> edgeRules = entry.getValue();
410	            if (CollectionUtils.isEmpty(edgeRules)) {
411	                continue;
412	            }
413	
414	            // 前置节点的时间(同indexId下的最早时间)
415	            Long relateNodeId = orderNode != null ? orderNode.getRelateNodeId() : dispatchNode.getRelateNodeId();
416	            String supplierId = orderNode != null ? orderNode.getFulfillmentDeliveryId() : dispatchNode.getSupplierId();
417	            String orderNo = orderNode != null ? orderNode.getOrderNo() : dispatchNode.getOrderNo();
418	            Long dispatchId = dispatchNode != null ? dispatchNode.getDispatchId() : null;
419	            Integer restartCount = dispatchNode != null ? dispatchNode.getRestartCount() : null;
420	
421	            CalculatedTimeline calculateTime = calculateTimelines(edgeRules, nodeTimeTrackMap, relateNodeId, supplierId, orderNo, dispatchId, restartCount, orderNode != null);
422	            if (calculateTime == null) {
423	                continue;
424	            }
425	
426	            BigDecimal innerInterval;
427	            Date factStartTime;
428	            if (orderNode != null) {
429	                innerInterval = orderNode.getInnerInterval();
430	                factStartTime = orderNode.getFactStartTime();
431	            } else {
432	                innerInterval = dispatchNode.getInnerInterval();
433	                factStartTime = dispatchNode.getFactStartTime();
434	            }
435	            if (!HolidayService.indicatorHolidayMap.containsKey(figureNode.getName())) {
436	                LOGGER.error("processRules计算出现不识别的indicatorName: {}", figureNode.getName());
437	            }
438	            // 自然日skipBitmask跳过春节+法定春节, 工作日读取indicatorHolidayMap
439	            int skipBitmask = HolidayService.CALENDAR_DAY_BITMASK;
440	            if (HolidayService.WORK_DAYS.equals(calculateTime.getScheduleRule().getTimeType())) {
441	                skipBitmask = HolidayService.indicatorHolidayMap.get(figureNode.getName());
442	            }
443	            Date expectStartTime = TimeProcessor.processTime(calculateTime.getScheduleRule().getTimeRef(), calculateTime.getScheduleRule().getInterval(),
444	                    calculateTime.getStartTime(), skipBitmask, calendars);
445	            // 当耗时任务已经实际开始时, 使用实际开始时间计算考核结束时间
446	            Date startTime = innerInterval.compareTo(BigDecimal.ZERO) > 0 && factStartTime != null ? factStartTime : expectStartTime;
447	            Date ExpectEndTime = TimeProcessor.processTime("之后", innerInterval, startTime, skipBitmask, calendars);
448	            CalculatedTimeline calTime = CalculatedTimeline.builder()
449	                    .expectStartTime(expectStartTime)
450	                    .expectTime(ExpectEndTime)
451	                    .startTime(calculateTime.getStartTime())
452	                    .scheduleRule(calculateTime.getScheduleRule())
453	                    .realFlag(calculateTime.getRealFlag())
454	                    .build();
455	            calculatedTimelines.add(calTime);
456	            LOGGER.info("figureCore同index下: index: {}, rules: {}, calTime: {}", entry.getKey(), JsonUtil.obj2JsonStr(edgeRules), JsonUtil.obj2JsonStr(calTime));
457	        }
458	        CalculatedTimeline evalTime = evalOrderService.selectFinalTimeline(funcName, calculatedTimelines);
459	        if (evalTime != null) {
460	            evalTime.setRealFlag(ruleMap.size() == calculatedTimelines.size()
461	                    && calculatedTimelines.stream().allMatch(t -> t.getRealFlag() == 1) ? 1 : 0);
462	            LOGGER.info("figureCore最终考核计算结果: evalTime: {}", JsonUtil.obj2JsonStr(evalTime));
463	        }
464	        return evalTime;
465	    }
