467	    private CalculatedTimeline calculateTimelines(List<ScheduleEdgeRule> edgeRules, Map<String, NodeTimeTrackV2> nodeTimeTrackMap,
468	                                                  Long relateNodeId, String supplierId, String orderNo, Long dispatchId,
469	                                                  Integer restartCount, Boolean orderFigure) {
470	        // 获取同ruleId下计算需要的前置节点时间
471	        List<CalculatedTimeline> result = new ArrayList<>();
472	        for (ScheduleEdgeRule scheduleRule : edgeRules) {
473	            String codeFrom = scheduleRule.getCodeFrom();
474	            NodeTimeTrackV2 nodeTimeTrack = nodeTimeTrackMap.getOrDefault(codeFrom, null);
475	            if (nodeTimeTrack == null) {
476	                continue;
477	            }
478	            List<NodeTimeTrackV2.TimeInfo> timeInfos = nodeTimeTrack.getTimeInfos();
479	            if (CollectionUtils.isEmpty(timeInfos)) {
480	                continue;
481	            }
482	
483	            // 数据过滤
484	            timeInfos = filterTimeInfos(timeInfos, relateNodeId, supplierId, orderNo, dispatchId, restartCount, scheduleRule.getCross(), orderFigure);
485	            if (CollectionUtils.isEmpty(timeInfos)) {
486	                continue;
487	            }
488	
489	            List<TimeTrackRecord> completeTrackRecords = new ArrayList<>();
490	            List<TimeTrackRecord> assessmentTrackRecords = new ArrayList<>();
491	
492	            for (NodeTimeTrackV2.TimeInfo timeInfo : timeInfos) {
493	                if (timeInfo.getCompleteTime() != null) {
494	                    completeTrackRecords.add(new TimeTrackRecord(1, timeInfo.getCompleteTime()));
495	                } else if (timeInfo.getAssessmentTime() != null) {
496	                    assessmentTrackRecords.add(new TimeTrackRecord(0, timeInfo.getAssessmentTime()));
497	                }
498	            }
499	            if (completeTrackRecords.isEmpty() && assessmentTrackRecords.isEmpty()) {
500	                continue;
501	            }
502	
503	            TimeTrackRecord timeTrackRecord;
504	            if (!completeTrackRecords.isEmpty()) {
505	                completeTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime).reversed());
506	                timeTrackRecord = completeTrackRecords.get(0);
507	            } else {
508	                assessmentTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime).reversed());
509	                timeTrackRecord = assessmentTrackRecords.get(0);
510	            }
511	            result.add(CalculatedTimeline.builder()
512	                    .startTime(timeTrackRecord.getTime())
513	                    .realFlag(timeTrackRecord.getRealFlag())
514	                    .scheduleRule(scheduleRule)
515	                    .build());
516	        }
517	        if (result.isEmpty()) {
518	            return null;
519	        }
520	        // 返回最早
521	        result.sort(Comparator.comparing(CalculatedTimeline::getStartTime));
522	        return CalculatedTimeline.builder()
523	                .scheduleRule(result.get(0).getScheduleRule())
524	                .startTime(result.get(0).getStartTime())
525	                .realFlag(result.stream().anyMatch(t -> t.getRealFlag() == 1) ? 1 : 0)
526	                .build();
527	    }
