529	    /**
530	     * 过滤前置时间节点
531	     * */
532	    private List<NodeTimeTrackV2.TimeInfo> filterTimeInfos(List<NodeTimeTrackV2.TimeInfo> timeInfos, Long relateNodeId, String supplierId,
533	                                                           String orderNo, Long dispatchId, Integer restartCount, Boolean cross, Boolean orderFigure) {
534	        List<NodeTimeTrackV2.TimeInfo> res;
535	
536	        if (!apolloConfig.isFigureByAssessmentV2() && orderFigure) {
537	            // 货单开关关闭时, 只保留有完成时间的轨迹节点
538	            // 不需要删除考核时间, 因为有完成时间的话就不会使用考核时间
539	            timeInfos = timeInfos.stream()
540	                    .filter(t -> t.getCompleteTime() != null)
541	                    .collect(Collectors.toList());
542	        }
543	
544	        // 跨品类场景下, 直接返回所有轨迹节点
545	        if (cross) {
546	            return timeInfos;
547	        }
548	
549	        // 如果能命中relateNodeId, 直接返回命中的轨迹节点
550	        // 适用于<下单找复尺>, <复尺找通知复尺>
551	        if (relateNodeId != null) {
552	            res = timeInfos.stream()
553	                    .filter(t -> relateNodeId.equals(t.getNodeId()))
554	                    .collect(Collectors.toList());
555	            if (!res.isEmpty()) {
556	                return res;
557	            }
558	        }
559	
560	        // 对轨迹数据做过滤, 要求和目标实例的供应商相同
561	        if (StringUtils.isNotEmpty(supplierId)) {
562	            List<NodeTimeTrackV2.TimeInfo> filterSupplierTimeInfos = timeInfos.stream()
563	                    .filter(t -> StringUtils.isEmpty(t.getSupplierId()) || t.getSupplierId().equals(supplierId))
564	                    .collect(Collectors.toList());
565	            // 如果过滤后没有数据, 允许查询支持跨供应商的轨迹
566	            if (filterSupplierTimeInfos.isEmpty()) {
567	                filterSupplierTimeInfos = timeInfos.stream()
568	                        .filter(NodeTimeTrackV2.TimeInfo::isCrossSupplier)
569	                        .collect(Collectors.toList());
570	            }
571	            timeInfos = filterSupplierTimeInfos;
572	        }
573	
574	        // 对轨迹数据做过滤, 要求和目标实例的orderNo相同
575	        if (StringUtils.isNotEmpty(orderNo)) {
576	            timeInfos = timeInfos.stream()
577	                    .filter(t -> StringUtils.isEmpty(t.getOrderNo()) || t.getOrderNo().equals(orderNo))
578	                    .collect(Collectors.toList());
579	        }
580	
581	        // 果能命中dispatchId和restartCount, 直接返回命中的轨迹节点
582	        if (dispatchId != null && restartCount != null && restartCount > 0) {
583	            res = timeInfos.stream()
584	                    .filter(t -> dispatchId.equals(t.getDispatchId()) && restartCount.equals(t.getRestartCount()))
585	                    .collect(Collectors.toList());
586	            if (!res.isEmpty()) {
587	                return res;
588	            }
589	        }
590	        return timeInfos;
591	    }
