593	    private List<ScheduleEdgeRule> filterRuleByOrderNode(List<ScheduleEdgeRule> rules, ScheduleOrderNode orderNode, ScheduleDispatchNode dispatchNode) {
594	        String categoryId = orderNode != null ? orderNode.getCategoryId() : dispatchNode.getCategoryId();
595	        Byte deliveryType = orderNode != null ? orderNode.getDeliveryType() : null;
596	        String deliveryId = orderNode != null ? orderNode.getFulfillmentDeliveryId() : dispatchNode.getSupplierId();
597	        Boolean isRestart = orderNode == null && dispatchNode.getRestartCount() > 0;
598	        Boolean isReplenish = orderNode != null ? orderNode.getReplenish() : dispatchNode.getReplenish();
599	        String name = orderNode != null ? IndicatorScheduleDAGService.ORDER_EVENT_NAME.get(orderNode.getTaskType())
600	                : IndicatorScheduleDAGService.DISPATCH_EVENT_NAME.get(dispatchNode.getTaskType() + "_" + dispatchNode.getNodeType());
601	
602	        // 过滤考核规则
603	        // 按照任务类型先过滤一下
604	        // deliveryType = -1 不限制
605	        // deliveryId = -1 不限制
606	        // isRestart 是否重启
607	        // isReplenish 是否返补
608	        return rules.stream()
609	                .filter(r -> r.getIndicatorName().equals(name)
610	                        && r.getCategoryId().equals(categoryId)
611	                        && (r.getDeliveryType().equals((byte) -1) || r.getDeliveryType().equals(deliveryType))
612	                        && (r.getDeliveryId().equals("-1") || r.getDeliveryId().equals(deliveryId))
613	                        && isRestart.equals(r.getRestart())
614	                        && isReplenish.equals(r.getReplenish()))
615	                .collect(Collectors.toList());
616	    }
