685	    private void initInnerIntervalAndRelateNodeId(ScheduleAllNode scheduleAllNode, Map<String, String> scheduleCodeToName, List<DeliveryProcessTaskDTO> tasks) {
686	
687	        Map<Long, DeliveryProcessTaskDTO> taskMap = tasks.stream()
688	                .collect(Collectors.toMap(DeliveryProcessTaskDTO::getId, Function.identity(), (v1, v2) -> v2));
689	
690	        List<DeliveryProcessTaskDTO> filterTasks = tasks.stream()
691	                // 如果一个实例有耗时, 或者存在指定关系, 则保留
692	                .filter(t -> (t.getPeriod() != null && t.getPeriod().compareTo(BigDecimal.ZERO) > 0)
693	                        || (t.getRelationTaskId() != null && t.getRelationTaskId() > 0))
694	                // 未完成的任务(dispatchNode == null)放在最后
695	                .sorted(Comparator.comparing(DeliveryProcessTaskDTO::getDispatchNodeId,
696	                        Comparator.nullsLast(Comparator.reverseOrder())))
697	                .collect(Collectors.toList());
698	
699	        // nodeTask -> name
700	        // name -> schedule/order, taskType
701	        // scheduleAllNode, schedule/order, taskType, businessId -> innerInterval
702	
703	        // 货单载体上记relateNodeId, 下单找到对应的复尺
704	        // 用工载体上记relateNodeId, 任务找到对应的通知任务
705	        for (DeliveryProcessTaskDTO task : filterTasks) {
706	            if (task.getNodeCode().startsWith(task.getTaskType() + "_")) {
707	                // 只处理携带品类信息的数据
708	                String categoryId = task.getNodeCode().replace(task.getTaskType() + "_", "");
709	                String name = scheduleCodeToName.getOrDefault(task.getTaskType(), "");
710	                if (StringUtils.isNotEmpty(name)) {
711	                    List<Integer> entityInfo = IndicatorScheduleDAGService.EVENT_ENTITY.get(name);
712	                    if (entityInfo != null) {
713	                        Integer entityType = entityInfo.get(0);
714	                        // workbench & 主材任务 的taskType
715	                        Integer taskType = entityInfo.get(1);
716	                        // taskNode 主任任务特有
717	                        Integer taskNode = entityInfo.size() == 3 ? entityInfo.get(2) : null;
718	                        if (entityType.equals(IndicatorScheduleDAGService.ORDER_NODE)) {
719	                            for (ScheduleOrderNode orderNode : scheduleAllNode.getOrderNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
720	                                if (orderNode.getInnerInterval().compareTo(BigDecimal.ZERO) > 0
721	                                        || (!orderNode.getDeliveryType().equals(task.getDeliveryType()) && !FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode().equals(orderNode.getTaskType()))
722	                                        || !orderNode.getFulfillmentDeliveryId().equals(task.getSupplierCode())) {
723	                                    // 任务类型, 品类不同, 调过
724	                                    // 设置过了, 跳过
725	                                    // 非下单任务, 履约方式不同, 调过
726	                                    // 供应商不同, 跳过
727	                                    continue;
728	                                }
729	                                orderNode.setInnerInterval(task.getPeriod() != null ? task.getPeriod() : BigDecimal.ZERO);
730	                                if (!DEFAULT_TIME.equals(task.getFactStartTime())) {
731	                                    orderNode.setFactStartTime(DateUtil.string2Date(task.getFactStartTime()));
732	                                }
733	                                // 下单任务的relateNodeId指向复尺任务, 且下单任务只有一个可直接配置
734	                                if (task.getRelationTaskId() != null
735	                                        && task.getRelationTaskId() > 0
736	                                        && taskMap.containsKey(task.getRelationTaskId())
737	                                        && orderNode.getTaskType().equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())) {
738	                                    orderNode.setRelateNodeId(taskMap.get(task.getRelationTaskId()).getDispatchNodeId());
739	                                }
740	                            }
741	                        }
742	                        if (entityType.equals(IndicatorScheduleDAGService.DISPATCH_NODE)) {
743	                            for (ScheduleDispatchNode dispatchNode : scheduleAllNode.getDispatchNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
744	                                if (dispatchNode.getInnerInterval().compareTo(BigDecimal.ZERO) > 0
745	                                        || !dispatchNode.getSupplierId().equals(task.getSupplierCode())
746	                                        || !dispatchNode.getNodeType().equals(taskNode)) {
747	                                    // 设置过了, 跳过
748	                                    // 任务类型, 节点类型, 品类, 供应商有任何不同, 跳过
749	                                    continue;
750	                                }
751	                                dispatchNode.setInnerInterval(task.getPeriod() != null ? task.getPeriod() : BigDecimal.ZERO);
752	                                if (!DEFAULT_TIME.equals(task.getFactStartTime())) {
753	                                    dispatchNode.setFactStartTime(DateUtil.string2Date(task.getFactStartTime()));
754	                                }
755	                                if (dispatchNode.getNodeId().equals(task.getDispatchNodeId())
756	                                        && taskMap.containsKey(task.getRelationTaskId())) {
757	                                    // 复尺任务已经完成的话, 让复尺任务指向通知复尺
758	                                    // relateNodeId值可能是错的, 在这里也可以修正
759	                                    dispatchNode.setRelateNodeId(taskMap.get(task.getRelationTaskId()).getDispatchNodeId());
760	                                } else if ((dispatchNode.getRelateNodeId() == null || dispatchNode.getRelateNodeId() == 0)
761	                                        && task.getDispatchNodeId() == null
762	                                        && task.getRelationTaskId() != null
763	                                        && task.getRelationTaskId() > 0
764	                                        && taskMap.containsKey(task.getRelationTaskId())) {
765	                                    // 复尺任务未完成时, 将剩余的复尺任务(理论上只有一个)指向通知复尺
766	                                    dispatchNode.setRelateNodeId(taskMap.get(task.getRelationTaskId()).getDispatchNodeId());
767	                                }
768	                            }
769	                        }
770	                    }
771	                }
772	            }
773	        }
774	    }
