789	                        .filter(t -> DeleteStatusEnum.NO.getCode().equals(t.getStandardDeleteStatus()))
790	                        .collect(Collectors.toList());
791	            } catch (RpcException e) {
792	                throw new RpcException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "constructionScheduleRpcService.queryScheduleNode获取工期数据异常", e);
793	            }
794	            dataContext.setTasks(tasks);
795	
796	            // 整理出工期数据
797	            dataContext.setConstructionList(new ArrayList<>());
798	            for (DeliveryProcessTaskDTO task : tasks) {
799	                if (EnumTransformUtil.CONSTRUCTION_ACTION_TYPE_SET.contains(task.getNodeCode())) {
800	                    String time = DEFAULT_TIME.equals(task.getFormTime()) ? task.getPredictStartTime() : task.getFormTime();
801	                    dataContext.getConstructionList().add(ConstructionScheduleDTO.builder()
802	                            .sequenceCode(task.getNodeCode())
803	                            .endDate(time.substring(0, 10))
804	                            .build());
805	                }
806	            }
807	
808	            // 整理基装包数据
809	            dataContext.setBasicPackageTasks(tasks.stream()
810	                    .filter(t -> EnumTransformUtil.BASIC_PACKAGE_ACTION_TYPE_SET.contains(t.getTaskType()))
811	                    .collect(Collectors.toList()));
812	
813	            // 一次性从主材任务获取全部数据
814	            TaskDispatchDetailSimpleParam taskDispatchDetailSimpleParam = new TaskDispatchDetailSimpleParam();
815	            taskDispatchDetailSimpleParam.setProjectOrderId(projectOrderDto.getProjectOrderId());
