817	            taskDispatchDetailSimpleParam.setNodeStates(Collections.singletonList(YnEnum.YES.getCode()));
818	            List<TaskDispatchDetailSimpleDTO> dispatchDetails = edarStarlordRpc.taskDetail(taskDispatchDetailSimpleParam);
819	            dataContext.setTaskDispatchDetailSimpleDTOS(dispatchDetails);
820	            dataContext.setDispatchSupplierMap(dispatchDetails.stream().collect(Collectors.toMap(
821	                    TaskDispatchDetailSimpleDTO::getTaskDispatchId,
822	                    TaskDispatchDetailSimpleDTO::getSupplierCode,
823	                    (v1, v2) -> v1
824	            )));
825	
826	            // 一次性从OFC全部数据
827	            dataContext.setOrderFlowTimes(new ArrayList<>());
828	            List<ScheduleEventNode> ofcEventNodeList = eventTypeMap.getOrDefault(EventTypeEnum.OMS_OFC.getValue(), new ArrayList<>());
829	            Set<String> orderNos = ofcEventNodeList.stream()
830	                    .map(eventNode -> categoryOrderNoMap.get(eventNode.getCategoryId()))
831	                    .filter(Objects::nonNull)
832	                    .flatMap(Collection::stream)
833	                    .collect(Collectors.toSet());
834	            if (!orderNos.isEmpty()) {
835	                List<DispatchReceiveDto> orderFlowTimes = ofcRpc.queryDispatchInfoByFlowMainNoList(new ArrayList<>(orderNos));
836	                for (DispatchReceiveDto of : orderFlowTimes) {
837	                    // 对于送达成功来说, 代销直送是6166, 其余是5020. 这里统一将5020转为6166
838	                    // 如果是自提, 快递模式的话是没有送达成功的, 这是考核不应该配置送达作为前置条件
839	                    if (DispatchReceiveActionTypeEnum.TMS_NOTIFY_DRIVER_TRANSIT_FINISH.getCode().equals(of.getActionType())) {
840	                        of.setActionType(DispatchReceiveActionTypeEnum.SDM_NOTIFY_TRANSIT_SUCCESS.getCode());
841	                    }
842	                }
843	                dataContext.setOrderFlowTimes(orderFlowTimes);
844	            }
845	
846	            // 一次性从OMS全部数据
847	            // 暂无, 以后再说
848	            dataContext.setSubOrderComplexDtos(new ArrayList<>());
849	
850	            // 一次性获取全部返补数据
851	            // 暂无, 以后再说
852	            dataContext.setReplenishReceiveDtos(new ArrayList<>());
853	
854	            // 一次性拉取施工包数据
855	            // 暂无, 以后再说
856	            dataContext.setCubeDtos(new ArrayList<>());
857	
858	            // 一次性拉取fulfillment数据
859	            dataContext.setFulfillmentTasks(new HashMap<>());
860	            FulfillmentTaskExample example = new FulfillmentTaskExample();
861	            example.createCriteria()
862	                    .andProjectCodeEqualTo(projectOrderId)
