865	            Map<String, List<FulfillmentTask>> taskMap = fulfillmentTasks.stream()
866	                    .collect(Collectors.groupingBy(t -> t.getCategoryId() + "_" + t.getTaskType(), Collectors.toList()));
867	            dataContext.setFulfillmentTasks(taskMap);
868	
869	        } catch (RpcException e) {
870	            LOGGER.info("buildScheduleTimeDataContext，获取数据异常: ", e);
871	        }
872	        return dataContext;
873	    }
