875	    private IndicatorEvalSDO createIndicatorEvalSDO(CalculatedTimeline evalTime, Map<String, NodeTimeTrackV2> nodeTimeTrackMap,
876	                                                    ScheduleEventNode figureNode, ScheduleOrderNode orderNode, ScheduleDispatchNode dispatchNode) {
877	        IndicatorEvalSDO indicatorEvalSDO = new IndicatorEvalSDO();
878	        ScheduleEdgeRule expectRule = evalTime.getScheduleRule();
879	        indicatorEvalSDO.setIndicatorName(expectRule.getIndicatorName());
880	        indicatorEvalSDO.setExpectStartTime(DateUtil.formatTime(evalTime.getExpectStartTime()));
881	        indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(evalTime.getExpectTime()));
882	        indicatorEvalSDO.setInterval(expectRule.getInterval() == null ? BigDecimal.ZERO : expectRule.getInterval());
883	        indicatorEvalSDO.setAssessDayType(expectRule.getTimeType() != null ? expectRule.getTimeType() : 2);
884	        indicatorEvalSDO.setStartTime(DateUtil.formatTime(evalTime.getStartTime()));
885	        indicatorEvalSDO.setEndNode(RuleUnit.getRealNode(expectRule.getCodeTo()));
886	        indicatorEvalSDO.setMatchStartNode(expectRule.getCodeFrom());
887	        indicatorEvalSDO.setEvaluation(0);
888	
889	        // 尝试获取轨迹结束时间
890	        NodeTimeTrackV2 nodeTrack = nodeTimeTrackMap.getOrDefault(figureNode.getUniqCode(), null);
891	        if (nodeTrack != null) {
892	            List<NodeTimeTrackV2.TimeInfo> timeInfos = nodeTrack.getTimeInfos().stream()
893	                    .filter(o -> Objects.nonNull(o.getCompleteTime()))
894	                    .sorted(Comparator.comparing(NodeTimeTrackV2.TimeInfo::getCompleteTime))
895	                    .collect(Collectors.toList());
896	            for (NodeTimeTrackV2.TimeInfo timeInfo : timeInfos) {
897	                if (orderNode != null
898	                        && orderNode.getOrderNo().equals(timeInfo.getOrderNo())) {
899	                    indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(timeInfo.getCompleteTime()));
900	                    break;
901	                }
902	                if (dispatchNode != null
903	                        && dispatchNode.getDispatchId().equals(timeInfo.getDispatchId())
904	                        && dispatchNode.getRestartCount().equals(timeInfo.getRestartCount())
905	                        && dispatchNode.getNodeId().equals(timeInfo.getNodeId())) {
906	                    indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(timeInfo.getCompleteTime()));
907	                    break;
908	                }
909	            }
910	        }
911	
912	        List<String> indicatorNodeList = new ArrayList<>(expectRule.getCodeFromList());
913	        indicatorNodeList.add(expectRule.getCodeTo());
914	        indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList.stream()
915	                .map(RuleUnit::getRealNode)
916	                .collect(Collectors.toList()));
917	        indicatorEvalSDO.setRealFlag(evalTime.getRealFlag());
918	        if (indicatorEvalSDO.getRealCompTime() != null
919	                && indicatorEvalSDO.getExpectCompTime() != null
920	                && DateUtil.string2Date(indicatorEvalSDO.getRealCompTime()).after(DateUtil.string2Date(indicatorEvalSDO.getExpectCompTime()))) {
921	            indicatorEvalSDO.setEvaluation(1);
922	        }
923	        return indicatorEvalSDO;
924	    }
