963	    private Boolean updateFulfillmentTask(String orderNo, String projectOrderId, String categoryId, String deliveryId, CalculatedTimeline evalTime,
964	                                          Integer taskType, Boolean replenishment) {
965	        if (evalTime == null) {
966	            return false;
967	        }
968	
969	        FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
970	        FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
971	        criteria.andProjectCodeEqualTo(projectOrderId);
972	        criteria.andTaskTypeEqualTo(taskType);
973	        criteria.andCategoryIdEqualTo(categoryId);
974	        criteria.andDeliveryIdEqualTo(deliveryId);
