230		private void executeCusCalculationRuleByNodeTo(IndicatorCalculationContext indicatorCalculationContext, IndicatorComputeRule indicatorComputeRule) {
231			Map<String, IndicatorEvalValBO.IndicatorEvalSDO> indicatorEvalSDOMap = new HashMap<>();
232			if(indicatorCalculationContext.getCusEval() != null) {
233				 indicatorEvalSDOMap = indicatorCalculationContext.getCusEval().stream().collect(Collectors.toMap(IndicatorEvalValBO.IndicatorEvalSDO::getIndicatorName, Function.identity(), (k1, k2) -> k1));
234			}
235			//本次的计算结果
236			IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = new IndicatorEvalValBO.IndicatorEvalSDO();
237	
238			List<CalculationRule> calculationRuleList = indicatorComputeRule.getCalculationRuleList();
239			FulfillmentNodeBo currentNode = indicatorCalculationContext.getCurrentNode();
240			Map<String, FulfillmentNodeBo> hisNodeMap =
241				indicatorCalculationContext.getHisNodes().stream().collect(Collectors.toMap(item -> item.getActionType().toString(),
242					Function.identity(), (k1, k2) -> k1));
243			//这个指标是否可以进行计算
244			Boolean canCalculate = true;
245			//字段判断当前阶段是否参与了本次计算,并非完全使用了历史节点
246			Boolean currentNodeInvolved = false;
247			//计算结果
248			Boolean result =  true;
249	
250	
251			for (CalculationRule calculationRule : calculationRuleList) {
252				// 只有结束节点 等于接收到事件的节点的时候进行计算.
253	
254				if (calculationRule.getNodeTo().equals(currentNode.getActionType().toString()) || hisNodeMap.containsKey(calculationRule.getNodeTo())) {
255					//判断当前节点是否参与到计算中，当前指标完全是依赖历史节点计算的 本次指标也不进行计算。
256					if(calculationRule.getNodeTo().equals(currentNode.getActionType().toString())){
257						currentNodeInvolved = true;
258					}
259					FulfillmentNodeBo tempNode = calculationRule.getNodeTo().equals(currentNode.getActionType().toString())? currentNode : hisNodeMap.get(calculationRule.getNodeTo());
260					List<String> nodeFrom = calculationRule.getNodeFrom();
261					Boolean hasFrontNodeInfo = false;
262					for (String from : nodeFrom) {
263						FulfillmentNodeBo fulfillmentNodeBo = hisNodeMap.get(from);
264						//如果查不到历史节点直接放弃这个计算
265						if(fulfillmentNodeBo == null ){
266							continue;
267						}
268						hasFrontNodeInfo = true;
269						Date operateTime = fulfillmentNodeBo.getOperateTime();
270						//如果预期考核时间早于 实际完成时间,表示这个指标延期了
271						Date expectTime = DateUtil.addSecond(operateTime, calculationRule.getInterval().multiply(new BigDecimal(24 * 60 * 60)).intValue());
272						if(expectTime.before(tempNode.getOperateTime()) ){
273							result &= true;
274							break;
275						}
276						result &= false;
277					}
278					canCalculate &= hasFrontNodeInfo;
279				}
280				//如果当前节点和 历史节点都在可以直接剪枝
281				else{
282					canCalculate &= false;
283				}
284	
285			}
286			if(canCalculate&& currentNodeInvolved){
287				//只有等于null的时候代表 这个指标真的参与计算了,否则就是没有参与计算 不进行记录
288				if(indicatorEvalSDOMap.containsKey(indicatorComputeRule.getIndicatorName())){
289					indicatorEvalSDO = indicatorEvalSDOMap.get(indicatorComputeRule.getIndicatorName());
290					indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(currentNode.getOperateTime()));
291					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()  ? 1 :0);
292					indicatorEvalSDO.setVersion(indicatorComputeRule.getVersion());
293					indicatorEvalSDO.setEvaluation(result ? 1:0);
294					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
295					indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
296					LOGGER.info("订单{}个性化指标{}已经计算过了结果为:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
297						indicatorComputeRule.getIndicatorName(),
298						JsonUtil.obj2JsonStr(indicatorEvalSDO));
299				}
300				else{
301					indicatorEvalSDO.setIndicatorName(indicatorComputeRule.getIndicatorName());
302					indicatorEvalSDO.setAssessmentRole(indicatorComputeRule.getAssessmentRoles());
303					indicatorEvalSDO.setVisibilityRole(indicatorComputeRule.getVisibilityRoles());
304					indicatorEvalSDO.setConfigType(indicatorComputeRule.getConfigType());
305					indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(new Date(1000)));
306					indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(currentNode.getOperateTime()));
307					indicatorEvalSDO.setEvaluation(result ? 1:0);
308					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()  ? 1 :0);
309					indicatorEvalSDO.setVersion(indicatorComputeRule.getVersion());
310					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
311					indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
312					indicatorCalculationContext.getCusEval().add(indicatorEvalSDO);
313					LOGGER.info("订单{}个性化指标{}计算结果为:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
314						indicatorComputeRule.getIndicatorName(),
315						JsonUtil.obj2JsonStr(indicatorEvalSDO));
316				}
317			}
318	
319		}
