466		private  void executeCusCalculationRuleByNodeFrom(IndicatorCalculationContext indicatorCalculationContext,
467														  IndicatorComputeRule indicatorComputeRule) {
468			Map<String, IndicatorEvalValBO.IndicatorEvalSDO> indicatorEvalSDOMap =
469				indicatorCalculationContext.getCusEval().stream().collect(Collectors.toMap(IndicatorEvalValBO.IndicatorEvalSDO::getIndicatorName, Function.identity(), (k1, k2)->k1));
470			//如果包含 且已经完成了 那么直接跳过不进行计算
471	
472			if(indicatorEvalSDOMap.containsKey(indicatorComputeRule.getIndicatorName())){
473				IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = indicatorEvalSDOMap.get(indicatorComputeRule.getIndicatorName());
474				//不需要重新计算的场景
475				//2 realCompTime && expectCompTime 都不为空的场景 代表这个一个完整的指标了 不需要重新计算。
476				String realCompTime = indicatorEvalSDO.getRealCompTime();
477				String expectCompTime = indicatorEvalSDO.getExpectCompTime();
478				if(StringUtils.isNotEmpty(expectCompTime) && expectCompTime.equals(DateUtil.formatTime(new Date(1000)))
479					&&  StringUtils.isNotEmpty(realCompTime) && realCompTime.equals(DateUtil.formatTime(new Date(1000)))){
480					return;
481				}
482			}
483	
484			//本次的计算结果
485			IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = new IndicatorEvalValBO.IndicatorEvalSDO();
486	
487			List<CalculationRule> calculationRuleList = indicatorComputeRule.getCalculationRuleList();
488			Date expectCompTime =  null;
489			BigDecimal leastInterval = null;
490			String endNode =null;
491			String startNode = null;
492			Boolean canCalculate = true;
493			Date startTime = null;
494			Map<String, FulfillmentNodeBo> hisNodeMap =
495				indicatorCalculationContext.getHisNodes().stream().collect(Collectors.toMap(item->item.getActionType().toString(),
496					Function.identity(),(k1, k2)->k1));
497			FulfillmentNodeBo currentNode = indicatorCalculationContext.getCurrentNode();
498	
499			for (CalculationRule calculationRule : calculationRuleList) {
500				Boolean hasFrontNodeInfo = false;
501				// 只有结束节点 等于接收到事件的节点的时候进行计算.
502				List<String> nodeFromList = calculationRule.getNodeFrom();
503				for (String nodeFrom : nodeFromList) {
504					//如果历史也没有from节点,当前节点也不是from节点。那么直接跳过
505					if (hisNodeMap.containsKey(nodeFrom) || (currentNode != null && nodeFrom.equals(currentNode.getActionType().toString()))) {
506						FulfillmentNodeBo fulfillmentNodeBo = (currentNode != null && nodeFrom.equals(currentNode.getActionType().toString())) ? currentNode : hisNodeMap.get(nodeFrom);
507						Date date = DateUtil.addSecond(fulfillmentNodeBo.getOperateTime(), calculationRule.getInterval().multiply(new BigDecimal(24 * 60 * 60)).intValue());
508						//如果 新计算的预期完成时间晚于
509						if (expectCompTime == null || expectCompTime.after(date)) {
510							expectCompTime = date;
511							leastInterval = calculationRule.getInterval();
512							endNode=calculationRule.getNodeTo();
513							startNode = nodeFrom;
514							startTime = fulfillmentNodeBo.getOperateTime();
515						}
516						hasFrontNodeInfo = true;
517					}
518				}
519				canCalculate &= hasFrontNodeInfo;
520			}
521				if(!canCalculate || expectCompTime == null){
522					LOGGER.info("订单{}个性化指标{}没有计算出预期完成时间",
523						indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(), indicatorComputeRule.getIndicatorName());
524					return;
525				}
526				List<String> indicatorNodeList = new ArrayList<>();
527				for (CalculationRule calculationRule : calculationRuleList) {
528					indicatorNodeList.addAll(calculationRule.getNodeFrom());
529					indicatorNodeList.add(calculationRule.getNodeTo());
530				}
531				//只有等于null的时候代表 这个指标真的参与计算了,否则就是没有参与计算 不进行记录
532				if (indicatorEvalSDOMap.containsKey(indicatorComputeRule.getIndicatorName())) {
533					indicatorEvalSDO = indicatorEvalSDOMap.get(indicatorComputeRule.getIndicatorName());
534					indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(expectCompTime));
535					Date time = StringUtils.isNotEmpty(indicatorEvalSDO.getRealCompTime()) ?
536						DateUtil.parse(indicatorEvalSDO.getRealCompTime(),DateUtil.DATE_FMT_2) : new Date();
537					//如果预期完成时间 在当前时间之后。则表示当前指标是合法的
538					int evlRes = expectCompTime.before(time) ? 1 : 0;
539					indicatorEvalSDO.setEvaluation(evlRes);
540					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()? 1:0);
541					indicatorEvalSDO.setInterval(leastInterval);
542					indicatorEvalSDO.setEndNode(endNode);
543					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
544					indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList);
545					indicatorEvalSDO.setMatchStartNode(startNode);
546					indicatorEvalSDO.setStartTime(DateUtil.formatTime(startTime));
547					if(!indicatorEvalSDO.getEvaluation().equals(evlRes)){
548						indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
549					}
550					LOGGER.info("订单{}个性化指标{}已经计算计算预期完成时间结果为:{}",
551						indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
552						indicatorComputeRule.getIndicatorName(),
553						JsonUtil.obj2JsonStr(indicatorEvalSDO));
554					checkAndUpdateDisorderEventCus(indicatorCalculationContext, indicatorComputeRule, endNode);
555				} else {
556					indicatorEvalSDO.setIndicatorName(indicatorComputeRule.getIndicatorName());
557					indicatorEvalSDO.setAssessmentRole(indicatorComputeRule.getAssessmentRoles());
558					indicatorEvalSDO.setVisibilityRole(indicatorComputeRule.getVisibilityRoles());
559					indicatorEvalSDO.setConfigType(indicatorComputeRule.getConfigType());
560					indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(expectCompTime));
561					Date time = StringUtils.isNotEmpty(indicatorEvalSDO.getRealCompTime()) ?
562						DateUtil.parse(indicatorEvalSDO.getRealCompTime(),DateUtil.DATE_FMT_2) : new Date();
563					indicatorEvalSDO.setEvaluation(expectCompTime.before(time) ? 1 : 0);
564					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()? 1:0);
565					indicatorEvalSDO.setInterval(leastInterval);
566					indicatorEvalSDO.setEndNode(endNode);
567					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
568					indicatorEvalSDO.setMatchStartNode(startNode);
569					indicatorEvalSDO.setStartTime(DateUtil.formatTime(startTime));
570					indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList);
571					indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
572					indicatorCalculationContext.getCusEval().add(indicatorEvalSDO);
573					LOGGER.info("订单{}个性化指标{}计算计算预期完成时间结果为:{}",
574						indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(), indicatorComputeRule.getIndicatorName(),
