582		private void executeBaseCalculationRuleByNodeFrom(IndicatorCalculationContext indicatorCalculationContext,
583														   IndicatorComputeRule indicatorComputeRule) {
584				Map<String, IndicatorEvalValBO.IndicatorEvalSDO> indicatorEvalSDOMap =
585					indicatorCalculationContext.getBaseEval().stream().collect(Collectors.toMap(IndicatorEvalValBO.IndicatorEvalSDO::getIndicatorName, Function.identity(), (k1, k2)->k1));
586				if(indicatorEvalSDOMap.containsKey(indicatorComputeRule.getIndicatorName())){
587					IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = indicatorEvalSDOMap.get(indicatorComputeRule.getIndicatorName());
588					//不需要重新计算的场景
589					//2 realCompTime && expectCompTime 都不为空的场景 代表这个一个完整的指标了 不需要重新计算。
590					String realCompTime = indicatorEvalSDO.getRealCompTime();
591					String expectCompTime = indicatorEvalSDO.getExpectCompTime();
592					if(StringUtils.isNotEmpty(expectCompTime) && expectCompTime.equals(DateUtil.formatTime(new Date(1000)))
593						&&  StringUtils.isNotEmpty(realCompTime) && realCompTime.equals(DateUtil.formatTime(new Date(1000)))){
594						return;
595					}
596				}
597				//本次的计算结果
598				IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = new IndicatorEvalValBO.IndicatorEvalSDO();
599	
600				List<CalculationRule> calculationRuleList = indicatorComputeRule.getCalculationRuleList();
601				Date expectCompTime =  null;
602				BigDecimal leastInterval = null;
603				String endNode =null;
604				String startNode = null;
605				Boolean canCalculate = true;
606				Date startTime = null;
607				Map<String, FulfillmentNodeBo> hisNodeMap =
608					indicatorCalculationContext.getHisNodes().stream().collect(Collectors.toMap(item->item.getActionType().toString(),
609						Function.identity(), (k1, k2)->k1));
610				FulfillmentNodeBo currentNode = indicatorCalculationContext.getCurrentNode();
611				for (CalculationRule calculationRule : calculationRuleList) {
612					// 只有结束节点 等于接收到事件的节点的时候进行计算.
613					List<String> nodeFromList = calculationRule.getNodeFrom();
614					Boolean hasFrontNodeInfo = false;
615					for (String nodeFrom : nodeFromList) {
616						//如果历史也没有from节点,当前节点也不是from节点。那么直接跳过
617						if (hisNodeMap.containsKey(nodeFrom) || (currentNode != null && nodeFrom.equals(currentNode.getActionType().toString()))) {
618							FulfillmentNodeBo fulfillmentNodeBo = (currentNode != null && nodeFrom.equals(currentNode.getActionType().toString())) ? currentNode : hisNodeMap.get(nodeFrom);
619							Date date = DateUtil.addSecond(fulfillmentNodeBo.getOperateTime(), calculationRule.getInterval().multiply(new BigDecimal(24 * 60 * 60)).intValue());
620							//如果 新计算的预期完成时间晚于
621							if (expectCompTime == null || expectCompTime.after(date)) {
622								expectCompTime = date;
623								leastInterval = calculationRule.getInterval();
624								endNode =calculationRule.getNodeTo();
625								startNode = nodeFrom;
626								startTime = fulfillmentNodeBo.getOperateTime();
627							}
628							hasFrontNodeInfo = true;
629						}
630					}
631					canCalculate &= hasFrontNodeInfo;
632				}
633				//如果不能计算,并且预期完成时间为空,则表示这个指标不参与计算
634				if(!canCalculate || expectCompTime == null){
635					LOGGER.info("订单{}底线指标{}没有计算出预期完成时间",
636						indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
637						indicatorComputeRule.getIndicatorName());
638					return;
639				}
640				List<String> indicatorNodeList = new ArrayList<>();
641				for (CalculationRule calculationRule : calculationRuleList) {
642					indicatorNodeList.addAll(calculationRule.getNodeFrom());
643					indicatorNodeList.add(calculationRule.getNodeTo());
644				}
645	
646				//只有等于null的时候代表 这个指标真的参与计算了,否则就是没有参与计算 不进行记录
647				if(indicatorEvalSDOMap.containsKey(indicatorComputeRule.getIndicatorName())){
648					indicatorEvalSDO = indicatorEvalSDOMap.get(indicatorComputeRule.getIndicatorName());
649					Date time = StringUtils.isNotEmpty(indicatorEvalSDO.getRealCompTime()) ?
650						DateUtil.parse(indicatorEvalSDO.getRealCompTime(),DateUtil.DATE_FMT_2) : new Date();
651						indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(expectCompTime));
652	
653					indicatorEvalSDO.setStartTime(DateUtil.formatTime(startTime));
654					//如果预期完成时间 在当前时间之后。则表示当前指标是合法的
655					int evlRes = expectCompTime.before(time) ? 1 : 0;
656					indicatorEvalSDO.setEvaluation(evlRes);
657					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()? 1:0);
658					indicatorEvalSDO.setVersion(indicatorComputeRule.getVersion());
659					indicatorEvalSDO.setInterval(leastInterval);
660					indicatorEvalSDO.setEndNode(endNode);
661					indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList);
662					indicatorEvalSDO.setMatchStartNode(startNode);
663					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
664					if(!indicatorEvalSDO.getEvaluation().equals(evlRes)){
665						indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
666					}
667					LOGGER.info("订单{}底线指标{}已经计算预期完成时间结果为:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
668						indicatorComputeRule.getIndicatorName(),
669						JsonUtil.obj2JsonStr(indicatorEvalSDO));
670					checkAndUpdateDisorderEventBase(indicatorCalculationContext, indicatorComputeRule, endNode);
671				}
672				else{
673					indicatorEvalSDO.setIndicatorName(indicatorComputeRule.getIndicatorName());
674					indicatorEvalSDO.setAssessmentRole(indicatorComputeRule.getAssessmentRoles());
675					indicatorEvalSDO.setVisibilityRole(indicatorComputeRule.getVisibilityRoles());
676					indicatorEvalSDO.setConfigType(indicatorComputeRule.getConfigType());
677					indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(expectCompTime));
678					Date time = StringUtils.isNotEmpty(indicatorEvalSDO.getRealCompTime()) ?
679						DateUtil.parse(indicatorEvalSDO.getRealCompTime(),DateUtil.DATE_FMT_2) : new Date();
680					indicatorEvalSDO.setEvaluation(expectCompTime.before(time) ? 1:0);
681					indicatorEvalSDO.setIsCusIndicator(indicatorComputeRule.getIsCus()? 1:0);
682					indicatorEvalSDO.setVersion(indicatorComputeRule.getVersion());
683					indicatorEvalSDO.setEndNode(endNode);
684					indicatorEvalSDO.setInterval(leastInterval);
685					indicatorEvalSDO.setIsRefSupplier(indicatorComputeRule.getIsRefSupplier());
686					indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList);
687					indicatorEvalSDO.setMatchStartNode(startNode);
688					indicatorEvalSDO.setStartTime(DateUtil.formatTime(startTime));
689					indicatorCalculationContext.getUpdatedEval().add(indicatorComputeRule.getIndicatorName());
690					indicatorCalculationContext.getBaseEval().add(indicatorEvalSDO);
691					LOGGER.info("订单{}底线指标{}计算计算预期完成时间结果为:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
692						indicatorComputeRule.getIndicatorName(),
693						JsonUtil.obj2JsonStr(indicatorEvalSDO));
694					checkAndUpdateDisorderEventBase(indicatorCalculationContext, indicatorComputeRule, endNode);
695				}
696	
697			}
