700			private  void checkAndUpdateDisorderEventBase(IndicatorCalculationContext indicatorCalculationContext,
701													 IndicatorComputeRule indicatorComputeRule, String endNode){
702	
703				//deepcopy
704	
705				//如果是乱序事件,则需要判断是否是乱序事件
706				Map<String, FulfillmentNodeBo> hisNodeMap =
707					indicatorCalculationContext.getHisNodes().stream().collect(Collectors.toMap(item->item.getActionType().toString(),
708						Function.identity(), (k1, k2)->k1));
709				LOGGER.info(" 订单号:{} 历史:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
710					JsonUtil.obj2JsonStr(hisNodeMap));
711				LOGGER.info("订单号:{}当前:{}",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),endNode);
712				if(!hisNodeMap.containsKey(endNode)){
713					return;
714				}
715				try {
716	
717					FulfillmentNodeBo originNode = indicatorCalculationContext.getCurrentNode();
718					FulfillmentNodeBo fulfillmentNodeBo = hisNodeMap.get(endNode);
719					indicatorCalculationContext.setCurrentNode(fulfillmentNodeBo);
720					LOGGER.info("开始进行计算乱序事件:{}",JsonUtil.obj2JsonStr(indicatorCalculationContext));
721					executeBaseCalculationRuleByNodeTo(indicatorCalculationContext, indicatorComputeRule);
722					indicatorCalculationContext.setCurrentNode(originNode);
723				}
724				catch (Exception e){
725					LOGGER.error("订单{}底线指标{}计算乱序事件异常",indicatorCalculationContext.getIndicatorOrderBO().getOrderNo(),
726						indicatorComputeRule.getIndicatorName(),e);
727				}
728			}
