230	    public ScheduleDAG getScheduleDAG(String projectOrderId) throws RpcException {
231	        ScheduleDAG res = null;
232	        Long version = constructionScheduleRpcService.getIndicatorVersion(projectOrderId);
233	        if (version == null) {
234	            LOGGER.info("无法构建考核DAG, projectOrderId={} 未配置排程规则", projectOrderId);
235	            return res;
236	        }
237	        String cacheString = SCHEDULE_DAG_CACHE.getIfPresent(version.toString());
238	        res = StringUtils.isBlank(cacheString) ? rebuild(version) : JsonUtil.jsonStr2Obj(cacheString, ScheduleDAG.class);
239	        res.setScheduleEdgeMap(new HashMap<>());
240	        res.setScheduleNodeMap(res.getScheduleEventNodes().stream()
241	                .collect(Collectors.toMap(ScheduleEventNode::getUniqCode, e -> e)));
242	
243	        // 因为深拷贝的原因, 引用类数据需要重新赋值
244	        // 初始化edgeMap
245	        for (ScheduleEdgeRule edgeRule : res.getScheduleEdgeRules()) {
246	            for (String codeFrom : edgeRule.getCodeFromList()) {
247	                String codeTo = edgeRule.getCodeTo();
248	                ScheduleEventNode nodeFrom = res.getScheduleNodeMap().get(codeFrom);
249	                ScheduleEventNode nodeTo = res.getScheduleNodeMap().get(codeTo);
250	                if (nodeFrom == null || nodeTo == null) {
251	                    LOGGER.info("scheduleDAG中未找到对应的节点, codeFrom: {}, codeTo: {}", codeFrom, codeTo);
252	                    continue;
253	                }
254	                String edgeKey = codeFrom + "," + codeTo;
255	                if (!res.getScheduleEdgeMap().containsKey(edgeKey)) {
256	                    ScheduleNodeEdge nodeEdge = ScheduleNodeEdge.builder()
257	                            .nodeFrom(nodeFrom)
258	                            .nodeTo(nodeTo)
259	                            .ruleList(new ArrayList<>())
260	                            .build();
261	                    res.getScheduleEdgeMap().put(edgeKey, nodeEdge);
262	
263	                    // 设置入度出度
264	                    nodeFrom.getEdgeOutList().add(nodeEdge);
265	                    nodeTo.getEdgeInList().add(nodeEdge);
266	                }
267	                res.getScheduleEdgeMap().get(edgeKey).getRuleList().add(edgeRule);
268	            }
269	        }
270	
271	        // 初始化nodeMap, 将入度出度为0的节点过滤掉
272	        res.setScheduleEventNodes(res.getScheduleEventNodes().stream()
273	                .filter(en -> !(en.getEdgeOutList().isEmpty() && en.getEdgeInList().isEmpty()))
274	                .collect(Collectors.toList()));
275	        res.setScheduleNodeMap(res.getScheduleEventNodes().stream()
276	                .collect(Collectors.toMap(ScheduleEventNode::getUniqCode, e -> e)));
277	        LOGGER.info("创建排程DAG成功, eventNodes: {}, edgeRules: {}", res.getScheduleEventNodes().size(), res.getScheduleEdgeRules().size());
278	        return res;
279	    }
