426	    private String getRuleId(ProcessNodeCfgDTO cfg, NodeAssessmentRuleCfgDTO ruleCfg) {
427	        return cfg.getMaterialCode() + "_" + cfg.getSupplierCode() + "_" + cfg.getDeliveryType() + "_" + cfg.getTaskType() + "_" + ruleCfg.getRestartType();
428	    }
