495	    private void dfs(ScheduleEventNode current, ScheduleAllNode scheduleAllNode,
496	                     Stack<String> circleVisited, List<ScheduleEventNode> figureNodeList) {
497	        // circleVisited用于判环
498	        // 遇环终止
499	        if (circleVisited.contains(current.getUniqCode())) {
500	            return;
501	        }
502	        circleVisited.push(current.getUniqCode());
503	        for (ScheduleNodeEdge edge : current.getEdgeOutList()) {
504	            ScheduleEventNode nextNode = edge.getNodeTo();
505	            // 存在符合配置的载体, 继续dfs
506	            ScheduleOrderDispatchNode scheduleOrderDispatchNode = getOrderDispatchNode(nextNode, scheduleAllNode);
507	            if (hasFilterNode(edge.getRuleList(), scheduleOrderDispatchNode)) {
508	                figureNodeList.add(nextNode);
509	                dfs(edge.getNodeTo(), scheduleAllNode, circleVisited, figureNodeList);
510	            }
511	        }
512	        circleVisited.pop();
513	    }
