515	    private Boolean hasFilterNode(List<ScheduleEdgeRule> rules, ScheduleOrderDispatchNode scheduleOrderDispatchNode) {
516	        // 符合条件的货单载体(考虑首次配置)
517	        for (ScheduleOrderNode orderNode : scheduleOrderDispatchNode.getOrderNodes()) {
518	            for (ScheduleEdgeRule rule : rules) {
519	                if (rule.getCategoryId().equals(orderNode.getCategoryId())
520	                        && (rule.getDeliveryId().equals("-1") || rule.getDeliveryId().equals(orderNode.getFulfillmentDeliveryId()))
521	                        && (rule.getDeliveryType().equals((byte) -1) || rule.getDeliveryType().equals(orderNode.getDeliveryType()))) {
522	                    return true;
523	                }
524	            }
525	        }
526	
527	        // 符合条件的用工载体(考虑首次配置 & 重启配置)
528	        for (ScheduleDispatchNode dispatchNode : scheduleOrderDispatchNode.getDispatchNodes()) {
529	            for (ScheduleEdgeRule rule : rules) {
530	                if (rule.getCategoryId().equals(dispatchNode.getCategoryId())
531	                        && (rule.getDeliveryId().equals("-1") || rule.getDeliveryId().equals(dispatchNode.getSupplierId()))
532	                        && ((rule.getRestart() && dispatchNode.getRestartCount() > 0)
533	                                || (!rule.getRestart() && dispatchNode.getRestartCount() == 0))) {
534	                    return true;
535	                }
536	            }
537	        }
538	        return false;
539	    }
