555	        for (IndicatorOrder order : orders) {
556	            String categoryId = order.getCategoryId();
557	            if (!orderNodeMap.containsKey(categoryId)) {
558	                orderNodeMap.put(categoryId, new HashMap<>());
559	            }
560	            for (Integer taskType : ORDER_NODE_TASK_TYPES) {
561	                if (!orderNodeMap.get(categoryId).containsKey(taskType)) {
562	                    orderNodeMap.get(categoryId).put(taskType, new ArrayList<>());
