564	                orderNodeMap.get(categoryId).get(taskType).add(ScheduleOrderNode.builder()
565	                        .id(order.getId())
566	                        .projectOrderId(order.getProjectOrderId())
567	                        .orderNo(order.getOrderNo())
568	                        .taskType(taskType)
569	                        .deliveryType(order.getDeliveryType())
570	                        .categoryId(order.getCategoryId())
571	                        .deliveryId(order.getDeliveryId())
572	                        .supplierId(order.getSupplierId())
573	                        .innerInterval(BigDecimal.ZERO)
574	                        .fulfillmentDeliveryId(order.getDeliveryType() != null && DeliveryTypeEnum.WAREHOUSE.getType().equals(order.getDeliveryType()) ?
575	                                order.getDeliveryId() : order.getSupplierId())
576	                        .replenish(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()))
577	                        .replacement(false)
578	                        .build()
579	                );
580	            }
581	        }
582	
583	        // 下单任务 需要用indicator_project_order和fulfillment_task关联查询
