599	        Map<String, FulfillmentTask> existsMap = placeOrders.stream()
600	                .collect(Collectors.toMap(
601	                        o -> o.getCategoryId() + "_" + o.getDeliveryId(),
602	                        Function.identity(),
603	                        (v1, v2) -> v2));
604	
605	        // 获取全部汰换标记
606	        FulfillmentTaskExtExample extExample = new FulfillmentTaskExtExample();
607	        extExample.createCriteria()
608	                .andReplacementEqualTo((byte) 1)
609	                .andProjectOrderIdEqualTo(projectOrderId);
610	        List<FulfillmentTaskExt> extList = fulfillmentTaskExtMapper.selectByExample(extExample);
611	        Set<Long> extSet = extList.stream().map(FulfillmentTaskExt::getTaskId).collect(Collectors.toSet());
612	
613	        projectOrders = projectOrders.stream()
614	                .filter(o -> existsMap.containsKey(o.getCategoryId() + "_" + o.getDeliveryId()))
