616	
617	        Map<Long, IndicatorProjectOrder> projectOrderMap = projectOrders.stream()
618	                .collect(Collectors.toMap(IndicatorProjectOrder::getId, o -> o));
619	
620	        for (IndicatorProjectOrder projectOrder : projectOrders) {
