626	            if (!orderNodeMap.get(categoryId).containsKey(taskType)) {
627	                orderNodeMap.get(categoryId).put(taskType, new ArrayList<>());
628	            }
629	            FulfillmentTask task = existsMap.get(projectOrder.getCategoryId() + "_" + projectOrder.getDeliveryId());
630	            orderNodeMap.get(categoryId).get(taskType).add(ScheduleOrderNode.builder()
631	                    .id(projectOrder.getId())
632	                    .projectOrderId(projectOrder.getProjectOrderId())
633	                    .orderNo("")
634	                    .taskType(taskType)
635	                    .deliveryType(projectOrder.getDeliveryType())
636	                    .categoryId(projectOrder.getCategoryId())
637	                    .deliveryId(projectOrder.getDeliveryId())
638	                    .supplierId("")
639	                    .fulfillmentDeliveryId(projectOrder.getDeliveryId())
640	                    .innerInterval(BigDecimal.ZERO)
641	                    .replenish(false)
