756	    public FigureScheduleParam getBaseEventsByDispatch(String projectOrderId, String categoryId, List<TaskDispatchDetailSimpleDTO.TaskNodeDetail> nodes,
757	                                                       Integer taskType, List<Integer> timeTypes) throws RpcException {
758	
759	        ScheduleDAG scheduleDAG = getScheduleDAG(projectOrderId);
760	        if (scheduleDAG == null || CollectionUtils.isEmpty(scheduleDAG.getScheduleEventNodes())) {
761	            return null;
762	        }
763	
764	        // 拿到DAG中的全部节点
765	        List<ScheduleEventNode> eventNodeList = scheduleDAG.getScheduleEventNodes();
766	
767	        // 将nodes转化为eventNode
768	        Map<String, String> NodeToCodeMap = getAllBaseEvents().stream()
769	                .collect(Collectors.toMap(
770	                        be -> be.getTaskInfo() + "_" + be.getTimeType(),
771	                        IndicatorBaseEvent::getCode,
772	                        (v1, v2) -> v1));
773	
774	        // 拼接taskType_nodeType_timeType作为key, 获取对应的eventNode的uniqCode
775	        Set<String> uniqCodeSet = new HashSet<>();
776	        Set<String> extCodeSet = new HashSet<>();
777	        for (TaskDispatchDetailSimpleDTO.TaskNodeDetail node : nodes) {
778	            Integer nodeType = node.getNodeType();
779	            if (node.getNoticeRetainTime().after(defaultDate) && timeTypes.contains(TimeTypeEnum.NOTICE_TIME.getValue())) {
780	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.NOTICE_TIME.getValue());
781	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
782	            }
783	            if (node.getGmtCreate().after(defaultDate) && timeTypes.contains(TimeTypeEnum.CREATE_TIME.getValue())) {
784	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.CREATE_TIME.getValue());
785	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
786	            }
787	            if (node.getEndTime().after(defaultDate) && timeTypes.contains(TimeTypeEnum.FACT_TIME.getValue())) {
788	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.FACT_TIME.getValue());
789	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
790	            }
791	            if (node.getStartTime().after(defaultDate)
792	                    && (timeTypes.contains(TimeTypeEnum.ACTIVE_TIME.getValue()) || (node.getRestartCount() != null && node.getRestartCount() > 0))) {
793	                // 重启任务的前置条件, 一律视为激活事件
794	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.ACTIVE_TIME.getValue());
795	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
796	            }
797	
798	            // 将当前节点(非重启)作为扩展节点, 进行计算
799	            String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.FACT_TIME.getValue());
800	            extCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
801	        }
802	
803	        uniqCodeSet.remove(null);
804	
805	        return FigureScheduleParam.builder()
806	                .projectOrderId(projectOrderId)
807	                .startNodes(eventNodeList.stream()
808	                        .filter(en -> uniqCodeSet.contains(en.getUniqCode()))
809	                        .collect(Collectors.toList()))
810	                .extNodes(eventNodeList.stream()
811	                        .filter(en -> extCodeSet.contains(en.getUniqCode()) && !uniqCodeSet.contains(en.getUniqCode()))
812	                        .collect(Collectors.toList()))
813	                .build();
814	    }
