915	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.COMPLETION_ACCEPTANCE.getSequenceCode()),
916	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.SOFT_ACCEPTANCE.getSequenceCode()),
917	                constructionMap.get(EnumTransformUtil.FIRST_BATCH_MATERIAL_ACCEPTANCE),
918	                constructionMap.get(EnumTransformUtil.SECOND_BATCH_MATERIAL_ACCEPTANCE));
919	
920	        String key = "scm-workbench:schedule-construction-diff:" + projectOrderId;
921	
922	        // redis不存在数据, 或数据不一致, 返回true
923	        Boolean res = !redisClient.existsKey(key) || !value.equals(redisClient.get(key));
924	        redisClient.set(key, value, apolloConfig.getScheduleInterval());
925	        return res;
926	    }
