928	    // 判断基装包是否有变化
929	    // forceAll=true 时, 忽略redis缓存, 认为全部基装包均存在diff
930	    public Set<String> checkBasicDiff(String projectOrderId, List<DeliveryProcessTaskDTO> tasks, boolean forceAll) {
931	        Set<String> res = new HashSet<>();
932	        for (DeliveryProcessTaskDTO task : tasks) {
933	            if (!EnumTransformUtil.BASIC_PACKAGE_ACTION_TYPE_SET.contains(task.getTaskType())) {
934	                continue;
935	            }
936	            String time;
937	            if (EnumTransformUtil.BASE_CONSTRUCTION_WORK_START.equals(task.getTaskType())) {
938	                time = !EvalScheduleOrderService.DEFAULT_TIME.equals(task.getFactStartTime()) ? task.getFactStartTime() : task.getPredictStartTime();
939	            } else {
940	                time = !EvalScheduleOrderService.DEFAULT_TIME.equals(task.getFactEndTime()) ? task.getFactEndTime() : task.getPredictEndTime();
941	            }
942	            String key = "scm-workbench:schedule-basic-package-diff:" + projectOrderId + ":" + task.getNodeCode();
943	            boolean diff = forceAll || !redisClient.existsKey(key) || !time.equals(redisClient.get(key));
944	            redisClient.set(key, time, apolloConfig.getScheduleInterval());
945	            if (diff) {
946	                res.add(task.getNodeCode());
947	            }
948	        }
949	        return res;
950	    }
