158		public List<DispatchReceiveDto> queryProblemOrderNodeTrack(IndicatorOrderBO orderBO) throws RpcException {
159			List<DispatchReceiveDto> res = new ArrayList<>();
160			if (!DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(orderBO.getSecondType())) {
161				// 非返补单，直接返回
162				return res;
163			}
164			List<String> orderNos = new ArrayList<>();
165			MasterDataQueryParam param = MasterDataQueryParam.builder()
166					.orderNos(Collections.singletonList(orderBO.getOrderNo()))
167					.paths(Collections.singletonList("sub_order_item.question_order_no"))
168					.build();
169			List<SubOrderDomain> subOrderDomains = omsRpc.querySubOrderMasterData(param);
170			if (CollectionUtils.isNotEmpty(subOrderDomains) && CollectionUtils.isNotEmpty(subOrderDomains.get(0).getSubOrderItem())) {
171				orderNos = subOrderDomains.get(0).getSubOrderItem().stream()
172						.map(SubOrderDomain.SubOrderItemDomain::getQuestionOrderNo)
173						.filter(Objects::nonNull)
174						.filter(StringUtils::isNotEmpty)
175						.collect(Collectors.toList());
176			}
177	
178			if (orderNos.isEmpty()) {
179				return res;
180			}
181			// 查询问题提报时间和审核时间（多个问题工单，取时间最晚的）
182			List<IssueOrderExternalInfoDTO> orderInfos = new ArrayList<>();
183			try {
184				orderInfos = artisanWorkOrderRpc.batchDetailsByOrderNos(orderNos);
185			} catch (RpcException e) {
186				LOGGER.info("获取返补单提报信息失败,未查询到补单提报信信息，orders:{}, err:", JsonUtil.obj2JsonStr(orderNos), e);
187			}
188			if (orderInfos == null || orderInfos.isEmpty()) {
189				return res;
190			}
191	
192			// 问题提出时间
193			List<Date> publishTimes = orderInfos.stream()
194					.map(item -> DateUtil.parse(item.getPublishTime(), DateUtil.DATE_FMT_2))
195					.sorted(Comparator.reverseOrder())
196					.collect(Collectors.toList());
197			Date publishTime = publishTimes.get(0);
198	
199			// 审核时间
200			List<Date> approveTimes = orderInfos.stream()
201					.filter(item -> StringUtils.isNotEmpty(item.getApproveTime()))
202					.map(item -> DateUtil.parse(item.getApproveTime(), DateUtil.DATE_FMT_2))
203					.sorted(Comparator.reverseOrder()).collect(Collectors.toList());
204			// 审核时间为空，取提出时间
205			Date approveTime = CollectionUtils.isNotEmpty(approveTimes) ? approveTimes.get(0) : publishTimes.get(0);
206	
207			res.add(buildReceiveDto(orderBO.getOrderNo(), DispatchReceiveActionTypeEnum.COE_PLATFORM_CREATE_ORDER, publishTime));
208			res.add(buildReceiveDto(orderBO.getOrderNo(), DispatchReceiveActionTypeEnum.COE_PLATFORM_CONFIRM, approveTime));
209			return res;
210		}
