253		public List<NodeTimeTrackV2> getNodeTimeTrackV2(Long projectOrderId, Map<String, List<String>> orderMapByCategory,
254														List<EventNode> eventNodes) {
255			if (CollectionUtils.isEmpty(eventNodes)) {
256				return Collections.emptyList();
257			}
258			Map<Integer, List<EventNode>> eventTypeMap = eventNodes.stream()
259					.collect(Collectors.groupingBy(EventNode::getEventType));
260	
261			// 构建数据源
262			BaseDataContext dataContext = buildTimeDataContext(projectOrderId, orderMapByCategory, eventTypeMap);
263	
264			List<NodeTimeTrackV2> list = Lists.newArrayList();
265			for (EventNode eventNode : eventNodes) {
266				TimeExtractor extractor = extractorFactory.findExtractor(EventTypeEnum.getEnumByValue(eventNode.getEventType()));
267				List<NodeTimeTrackV2> timeTrackList = extractor.getNodeTimeTrackV2(eventNode, dataContext, orderMapByCategory);
268				list.addAll(timeTrackList);
269			}
270	
271			list.forEach(nodeTimeTrackV2 -> {
272				List<NodeTimeTrackV2.TimeInfo> timeInfos = nodeTimeTrackV2.getTimeInfos();
273				timeInfos.forEach(t -> {
274					t.setAssessmentTime(DateUtil.filterInvalidDate(t.getAssessmentTime()));
275					t.setCompleteTime(DateUtil.filterInvalidDate(t.getCompleteTime()));
276					if (!apolloConfig.isFigureByAssessment()) {
277						// 开关关闭时, 剔除全部考核时间
278						t.setAssessmentTime(null);
279					}
280				});
281	
282				timeInfos.removeIf(t -> t.getAssessmentTime() == null && t.getCompleteTime() == null);
283			});
284	
285			LOGGER.info("getNodeTimeTrackV2加工轨迹:{}", JsonUtil.obj2JsonStr(list));
286			return list;
287		}
