289		private BaseDataContext buildTimeDataContext(Long projectOrderId, Map<String, List<String>> orderMapByCategory, Map<Integer, List<EventNode>> eventTypeMap) {
290	
291			BaseDataContext dataContext = new BaseDataContext();
292			dataContext.setDispatchSupplierMap(new HashMap<>());
293			dataContext.setFulfillmentTasks(new HashMap<>());
294			ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(projectOrderId);
295			dataContext.setProjectOrderDto(projectOrderDto);
296	
297			try {
298	
299				// 一次性从工期获取全部数据
300				List<ConstructionScheduleDTO> constructionList = constructionScheduleService.queryConstructionScheduleDetailNew(projectOrderDto.getProjectOrderId());
301				if (ProjectVersionUtil.V2_5_partial_decoration.equals(ProjectVersionUtil.getProjectVersionDetail(projectOrderDto))) {
302					// 翻新全案的特殊工期
303					List<DispatchReceiveDto> partialTimes = constructionScheduleService.restoreConstructionSchedulePartial(projectOrderId);
304					List<ConstructionScheduleDTO> partialSchedules = partialTimes.stream()
305							.map(p -> ConstructionScheduleDTO.builder()
306									.sequenceCode(String.valueOf(p.getActionType()))
307									.endTime(DateUtil.date2String(p.getOperationTime()))
308									.build())
309							.collect(Collectors.toList());
310					constructionList.addAll(partialSchedules);
311				}
312				dataContext.setConstructionList(constructionList);
313	
314				// 一次性从主材任务获取全部数据
315				TaskDispatchDetailSimpleParam taskDispatchDetailSimpleParam = new TaskDispatchDetailSimpleParam();
316				taskDispatchDetailSimpleParam.setProjectOrderId(projectOrderDto.getProjectOrderId());
317				List<TaskDispatchDetailSimpleDTO> taskDispatchDetailSimpleDTOS = edarStarlordRpc.taskDetail(taskDispatchDetailSimpleParam);
318				dataContext.setTaskDispatchDetailSimpleDTOS(taskDispatchDetailSimpleDTOS);
319	
320				// 一次性从OFC全部数据
321				List<EventNode> ofcEventNodeList = eventTypeMap.get(EventTypeEnum.OMS_OFC.getValue());
322				dataContext.setOrderFlowTimes(new ArrayList<>());
323				if (CollectionUtils.isNotEmpty(ofcEventNodeList)) {
324					Set<String> orderNos = ofcEventNodeList.stream()
325							.map(eventNode -> orderMapByCategory.get(eventNode.getCategoryId()))
326							.filter(Objects::nonNull)
327							.flatMap(Collection::stream)
328							.collect(Collectors.toSet());
329					List<DispatchReceiveDto> orderFlowTimes = ofcRpc.queryDispatchInfoByFlowMainNoList(new ArrayList<>(orderNos));
330					dataContext.setOrderFlowTimes(orderFlowTimes);
331				}
332	
333				// 一次性从OMS全部数据
334				dataContext.setSubOrderComplexDtos(new ArrayList<>());
335				List<EventNode> orderEventNodeList = eventTypeMap.get(EventTypeEnum.OMS_OMS.getValue());
336				if (CollectionUtils.isNotEmpty(orderEventNodeList)) {
337					Set<String> orderNos = orderEventNodeList.stream()
338							.map(eventNode -> orderMapByCategory.get(eventNode.getCategoryId()))
339							.filter(Objects::nonNull)
340							.flatMap(Collection::stream)
341							.collect(Collectors.toSet());
342	
343					SubOrderComplexQueryParam search = new SubOrderComplexQueryParam();
344					search.setOrderNos(new ArrayList<>(orderNos));
345					search.setPageSize(1000);
346					Page<SubOrderComplexDto> page = omsRpc.querySubOrderListInfoPost(search);
347					if (Objects.nonNull(page) && CollectionUtils.isNotEmpty(page.getList())) {
348						dataContext.setSubOrderComplexDtos(page.getList());
349					}
350				}
351	
352				// 一次性获取全部返补数据
353				dataContext.setReplenishReceiveDtos(new ArrayList<>());
354				List<EventNode> replenishNodeList = eventTypeMap.get(EventTypeEnum.REPLENISHMENT_APPLICATION.getValue());
355				if (CollectionUtils.isNotEmpty(replenishNodeList)) {
356					Set<String> orderNos = replenishNodeList.stream()
357							.map(eventNode -> orderMapByCategory.get(eventNode.getCategoryId()))
358							.filter(Objects::nonNull)
359							.flatMap(Collection::stream)
360							.collect(Collectors.toSet());
361					if (CollectionUtils.isNotEmpty(orderNos)) {
362						IndicatorOrderExample indicatorOrderExample = new IndicatorOrderExample();
363						indicatorOrderExample.createCriteria()
364								.andOrderNoIn(new ArrayList<>(orderNos))
365								.andSecondTypeIn(DicRuleNodeQueryServiceImpl.REPLENISH_SECOND_TYPE_LIST)
366								.andIsDeleteEqualTo((byte) 0);
367						List<IndicatorOrder> orderList = indicatorOrderMapper.selectByExample(indicatorOrderExample);
368						for (IndicatorOrder o : orderList) {
369							List<DispatchReceiveDto> replenishTrack = queryProblemOrderNodeTrack(IndicatorOrderBO.builder()
370									.orderNo(o.getOrderNo())
371									.secondType(o.getSecondType())
372									.build());
373							dataContext.getReplenishReceiveDtos().addAll(replenishTrack);
374						}
375					}
376				}
377	
378				// 一次性拉取施工包数据, 暂时先不拉取
379				dataContext.setCubeDtos(new ArrayList<>());
380	
381			} catch (RpcException ignored) {
382			}
383			return dataContext;
384		}
