386		public void doEval(List<EventNode> figureNodeList, List<NodeTimeTrackV2> getNodeTimeTrackV2,
387						   Map<String, List<IndicatorOrder>> orderMap, Map<String, List<IndicatorProjectOrder>> projectOrderMap,
388						   Map<String, Date> replacementPlaceOrderCreateTimeMap) {
389			Map<String, NodeTimeTrackV2> timeV2 = getNodeTimeTrackV2.stream()
390					.collect(Collectors.toMap(NodeTimeTrackV2::getCode, Function.identity(), (v1, v2) -> v1));
391	
392			// 若有汰换任务，提前取一次日历，避免每个节点重复读 Redis
393			Map<LocalDateTime, Integer> calendars = holidayService.getRecentCalendar();
394	
395			for (EventNode eventNode : figureNodeList) {
396				List<ExtendedEdgeRule> ruleList = extractRules(eventNode.getEdgeInList());
397				LOGGER.info("doEval粗过滤规则, eventNode: {}, ruleList: {}", eventNode.getCode(), JsonUtil.obj2JsonStr(ruleList));
398	
399				List<IndicatorProjectOrder> projectOrders = projectOrderMap.getOrDefault(eventNode.getCategoryId(), Collections.emptyList());
400				for (IndicatorProjectOrder indicatorProjectOrder : projectOrders) {
401					processProjectOrder(ruleList, indicatorProjectOrder, timeV2, eventNode, replacementPlaceOrderCreateTimeMap, calendars);
402				}
403	
