572		 * 汰换节点：考核时间取 max(计算考核时间, 任务创建时间 + N自然日)
573		 * N 由 Apollo 配置 replace_supplier_assessment_buffer_days 控制，默认为 3
574		 * 若触发调整，同步更新 figureTime.expectStartTime，并将新时间回写 baseEvalResult/cusEvalResult
575		 */
576		private void adjustExpectTimeForReplacement(Date taskCreateTime, FigureRes figureRes, Map<LocalDateTime, Integer> calendars) {
577			CalculatedTimeline figureTime = figureRes.getFigureTime();
578			if (taskCreateTime == null || figureTime == null || figureTime.getExpectTime() == null) {
579				return;
580			}
581			Date replaceAssessmentTime = DateUtil.localDateTime2Date(RuleUnit.figureAssessmentTime(
582					DateUtil.date2LocalDateTime(taskCreateTime), apolloConfig.getReplaceBufferDays(), HolidayService.CALENDAR_DAY_BITMASK, calendars));
583			if (replaceAssessmentTime.after(figureTime.getExpectTime())) {
584				figureTime.setExpectTime(replaceAssessmentTime);
585				syncEvalResultWithFigureTime(figureRes.getBaseEvalResult(), figureTime);
586				syncEvalResultWithFigureTime(figureRes.getCusEvalResult(), figureTime);
587			}
588		}
