616					eventNode.getCode(), JsonUtil.obj2JsonStr(order), JsonUtil.obj2JsonStr(projectOrder), JsonUtil.obj2JsonStr(sourceTypeRuleMap));
617			if (MapUtils.isEmpty(sourceTypeRuleMap)
618					|| (sourceTypeRuleMap.get(0).isEmpty() && sourceTypeRuleMap.get(1).isEmpty())) {
619				res.setIndicatorName(indicatorName);
620				return res;
621			}
622	
623			// 获取指标名称
624			String codeTo = eventNode.getCategoryId() + "_" + eventNode.getOfcCode();
625	
626			IndicatorEvalSDO baseEvalResult = null;
627			IndicatorEvalSDO cusEvalResult = null;
628			CalculatedTimeline baseCalculatedTimeline = null;
629			CalculatedTimeline cusCalculatedTimeline = null;
630	
631			for (Map.Entry<Integer, List<ExtendedEdgeRule>> rule : sourceTypeRuleMap.entrySet()) {
632				Integer sourceType = rule.getKey();
633				List<ExtendedEdgeRule> rules = rule.getValue();
634				if (rules.isEmpty()) {
635					continue;
636				}
637				CalculatedTimeline calculatedTimeline = processRules(sourceType, rules, timeV2, order != null ? order.getOrderNo() : null,
638						order, projectOrder, calendars, eventNode);
639				LOGGER.info("processCommon计算结果: order:{}, projectOrder:{}, calculatedTimeline: {}", order, projectOrder, JsonUtil.obj2JsonStr(calculatedTimeline));
640				if (calculatedTimeline == null) {
641					continue;
642				}
643				IndicatorEvalSDO indicatorEvalSDO = createIndicatorEvalSDO(calculatedTimeline, timeV2, eventNode, order, projectOrder);
644	
645				if (sourceType == 0) {
646					baseEvalResult = indicatorEvalSDO;
647					baseCalculatedTimeline = calculatedTimeline;
648				} else {
649					cusEvalResult = indicatorEvalSDO;
650					cusCalculatedTimeline = calculatedTimeline;
651				}
652			}
653	
654			CalculatedTimeline cusTime = cusCalculatedTimeline != null ? cusCalculatedTimeline : baseCalculatedTimeline;
655	
656			// 轨迹指向code
657			NodeTimeTrackV2 codeToTrack = timeV2.getOrDefault(codeTo , null);
658	
659			// 更新考核结果轨迹
660			updateTimeInfos(codeToTrack, cusTime, order);
661	
662			return FigureRes.builder()
663					.indicatorName(indicatorName)
664					.baseEvalResult(baseEvalResult)
665					.cusEvalResult(cusEvalResult)
666					.figureTime(cusTime)
667					.build();
668		}
