670		public List<IndicatorEvalSDO> mergeIndicator(List<IndicatorEvalSDO> indicatorEvalSDOList, IndicatorEvalSDO indicatorEvalSDO) {
671			if (Objects.isNull(indicatorEvalSDO)) {
672				return indicatorEvalSDOList;
673			}
674	
675			List<IndicatorEvalSDO> res = new ArrayList<>();
676			Set<String> indicatorSet = new HashSet<>();
677	
678			// 尽可能保持indicatorEvalSDOList内数据顺序不变, 这样可以减少MySQL更新的执行次数
679			for (IndicatorEvalSDO sdo : indicatorEvalSDOList) {
680				if (!indicatorSet.contains(sdo.getIndicatorName())) {
681					if (sdo.getIndicatorName().equals(indicatorEvalSDO.getIndicatorName())) {
682						res.add(indicatorEvalSDO);
683					} else {
684						res.add(sdo);
685					}
686					indicatorSet.add(sdo.getIndicatorName());
687				}
688			}
689	
690			if (!indicatorSet.contains(indicatorEvalSDO.getIndicatorName())) {
691				res.add(indicatorEvalSDO);
692			}
693			return res;
694		}
