696		private CalculatedTimeline processRules(Integer sourceType, List<ExtendedEdgeRule> rules, Map<String, NodeTimeTrackV2> timeV2, String orderNo,
697												IndicatorOrder order, IndicatorProjectOrder projectOrder, Map<LocalDateTime, Integer> calendars,
698												EventNode eventNode) {
699	
700			List<CalculatedTimeline> calculatedTimelines = new ArrayList<>();
701	
702			// 按照ruleId分组
703			List<List<ExtendedEdgeRule>> sortedGroups = rules.stream()
704					.collect(Collectors.groupingBy(EdgeRule::getRuleId))
705					.values()
706					.stream()
707					.sorted(Comparator.comparing((List<ExtendedEdgeRule> group) -> group.get(0).getVersion(), Comparator.nullsLast(Comparator.reverseOrder()))
708							.thenComparing(group -> group.get(0).getEndTime(), Comparator.nullsLast(Comparator.reverseOrder()))
709							.thenComparing(group -> group.get(0).getDeliveryType(), Comparator.nullsLast(Comparator.reverseOrder()))
710							.thenComparing(group -> group.get(0).getDeliveryIds(), Comparator.nullsLast(Comparator.reverseOrder()))
711					)
712					.collect(Collectors.toList());
713			LOGGER.info("processRules分组规则, 按ruleId分组，配送方式不等于不限制的靠前: eventNode: {}, order: {}, projectOrder:{}, sortedGroups: {}",
714					eventNode.getCode(), JsonUtil.obj2JsonStr(order), JsonUtil.obj2JsonStr(projectOrder), JsonUtil.obj2JsonStr(sortedGroups));
715	
716			for (List<ExtendedEdgeRule> groups : sortedGroups) {
717				if (CollectionUtils.isEmpty(groups)) {
718					continue;
719				}
720				String indicatorName = groups.get(0).getIndicatorName();
721				String funcName = groups.get(0).getFuncName();
722				Map<Integer, List<ExtendedEdgeRule>> ruleMap = groups.stream()
723						.collect(Collectors.groupingBy(EdgeRule::getIndexId));
724				for (Map.Entry<Integer, List<ExtendedEdgeRule>> entry : ruleMap.entrySet()) {
725					List<ExtendedEdgeRule> edgeRules = entry.getValue();
726					if (CollectionUtils.isEmpty(edgeRules)) {
727						continue;
728					}
729	
730					// 实际考核时间, 使用version匹配
731					VersionParam versionParam = getVersion(sourceType, indicatorName, order, projectOrder);
732	
733					long current = System.currentTimeMillis();
734					// 预测考核时间, 使用当前时间是否在规则的生效时间范围内
735					// 不在时间范围内不计算
736					if (versionParam == null && (current < edgeRules.get(0).getStartTime().getTime() || current > edgeRules.get(0).getEndTime().getTime())) {
737						continue;
738					}
739	
740					// 版本不一致
741					if (versionParam != null && !versionParam.getVersion().equals(edgeRules.get(0).getVersion())) {
742						continue;
743					}
744	
745					// 针对历史迁移数据的检查
746					// 版本一致, 但是时间检查不通过
747					if (versionParam != null && versionParam.getCheckTime() != null && versionParam.getCheckTime()
748							&& (versionParam.getStartTime().getTime() < edgeRules.get(0).getStartTime().getTime() || versionParam.getStartTime().getTime() > edgeRules.get(0).getEndTime().getTime())) {
749						continue;
750					}
751	
752					List<Timeline> result = calculateTimelines(edgeRules, timeV2, orderNo, eventNode);
753					if (CollectionUtils.isEmpty(result)) {
754						continue;
755					}
756					result.sort(Comparator.comparing(Timeline::getStartTime));
757					Timeline timeline = result.get(0);
758					if (Objects.isNull(timeline)) {
759						continue;
760					}
761	
762					if (!HolidayService.indicatorHolidayMap.containsKey(indicatorName)) {
763						LOGGER.error("processRules计算出现不识别的indicatorName: {}", indicatorName);
764					}
765					// 自然日skipBitmask跳过春节+法定春节, 工作日读取indicatorHolidayMap
766					int skipBitmask = HolidayService.CALENDAR_DAY_BITMASK;
767					if (HolidayService.WORK_DAYS.equals(timeline.getEdgeRule().getTimeType())) {
768						skipBitmask = HolidayService.indicatorHolidayMap.get(indicatorName);
769					}
770					Date computeTime = TimeProcessor.processTime(timeline.getEdgeRule().getTimeRef(), timeline.getEdgeRule().getInterval(),
771							timeline.getStartTime(), skipBitmask, calendars);
772					CalculatedTimeline calTime = new CalculatedTimeline();
773					calTime.setExpectTime(computeTime);
774					calTime.setStartTime(timeline.getStartTime());
775					calTime.setExtendedEdgeRule(timeline.getEdgeRule());
776					calTime.setRealFlag(result.stream().anyMatch(t -> t.getRealFlag() == 1) ? 1 : 0);
777					calculatedTimelines.add(calTime);
778					LOGGER.info("processRules同index下: index: {}, rules: {}, calTime: {}", entry.getKey(), JsonUtil.obj2JsonStr(edgeRules), JsonUtil.obj2JsonStr(calTime));
779				}
780				CalculatedTimeline calculatedTimeline = selectFinalTimeline(funcName, calculatedTimelines);
781				if (calculatedTimeline != null) {
782					calculatedTimeline.setRealFlag(ruleMap.size() == calculatedTimelines.size()
783							&& calculatedTimelines.stream().allMatch(t -> t.getRealFlag() == 1) ? 1 : 0);
784					LOGGER.info("processRules结果: calTime: {}", JsonUtil.obj2JsonStr(calculatedTimeline));
785					return calculatedTimeline;
786				}
787			}
788			return null;
789		}
