791		private VersionParam getVersion(Integer sourceType, String indicatorName, IndicatorOrder order, IndicatorProjectOrder projectOrder) {
792			if (order == null && projectOrder == null) {
793				return null;
794			}
795			String result;
796			if (order != null) {
797				result = sourceType == 0 ? order.getBaseEvalResultNew() : order.getCusEvalResultNew();
798			} else {
799				result = sourceType == 0 ? projectOrder.getBaseEvalResultNew() : projectOrder.getCusEvalResultNew();
800			}
801			if (StringUtils.isNotEmpty(result)) {
802				List<IndicatorEvalSDO> evalSDOS = JsonUtil.jsonStr2Obj(result, new TypeReference<List<IndicatorEvalSDO>>() {});
803				if (CollectionUtils.isNotEmpty(evalSDOS)) {
804					IndicatorEvalSDO target = evalSDOS.stream()
805						.filter(item -> item.getIndicatorName().equals(indicatorName))
806						.findFirst()
807						.orElse(null);
808					if (target != null && target.getRealFlag() != null && target.getRealFlag().equals(1)) {
809						VersionParam versionParam = new VersionParam();
810						versionParam.setVersion(target.getVersion());
811						versionParam.setCheckTime(target.getCheckTime() != null && target.getCheckTime());
812						versionParam.setStartTime(DateUtil.string2Date(target.getStartTime()));
813						return versionParam;
814					}
815				}
816			}
817			return null;
818		}
