996		private Boolean updateFulfillmentTask(String orderNo, String projectOrderId, String categoryId, String deliveryId, CalculatedTimeline baseTime,
997											  Integer taskType, Boolean replenishment) {
998			if (!apolloConfig.isUpdateTaskSwitch()) {
999				return false;
1000			}
1001			if (baseTime == null) {
1002				return false;
1003			}
1004			if (Objects.equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode(), taskType)
1005					&& StringUtils.isNotEmpty(orderNo)
1006					&& replenishment) {
1007				// 正向, 有货单号的, 下单任务不同步考核时间
1008				return false;
1009			}
1010			FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
1011			FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
1012			criteria.andProjectCodeEqualTo(projectOrderId);
1013			criteria.andTaskTypeEqualTo(taskType);
1014			criteria.andCategoryIdEqualTo(categoryId);
1015			criteria.andDeliveryIdEqualTo(deliveryId);
1016			if (StringUtils.isNotEmpty(orderNo)) {
1017				criteria.andRelateSubOrderNoEqualTo(orderNo);
1018			}
1019			criteria.andStatusNotEqualTo(FulfillmentTaskStatusEnum.CANCELED.getTypeCode());
1020			criteria.andReplenishmentEqualTo(replenishment ? FlowTypeEnum.REVERSE_ORDER.getCode() : FlowTypeEnum.NORMAL_ORDER.getCode());
1021	
1022			// 只更新考核时间发生变化的
1023			List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
1024			fulfillmentTasks.removeIf(task -> task.getAssessmentTime() != null
1025					&& task.getAssessmentTime().equals(baseTime.getExpectTime())
1026					&& task.getAssessmentType() != null
1027					&& task.getAssessmentType().equals(baseTime.getRealFlag()));
1028			if (!fulfillmentTasks.isEmpty()) {
1029				fulfillmentTaskExample.clear();
1030				fulfillmentTaskExample.createCriteria()
1031						.andIdIn(fulfillmentTasks.stream().map(FulfillmentTask::getId).collect(Collectors.toList()));
1032				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, TaskOperationContext.builder()
1033						.assessmentTime(baseTime.getExpectTime())
1034						.assessmentType(baseTime.getRealFlag())
1035						.build());
1036				return true;
1037			}
1038			return false;
1039		}
