1095	
1096			List<IndicatorEvalSDO> projectOrderIndicatorOrderCusEvl = JSONArray.parseArray(indicatorProjectOrder.getCusEvalResultNew(), IndicatorEvalSDO.class);
1097			if (CollectionUtils.isNotEmpty(projectOrderIndicatorOrderCusEvl)) {
1098				Optional<IndicatorEvalSDO> cusOpt = projectOrderIndicatorOrderCusEvl.stream()
1099					.filter(item -> item.getIndicatorName().equals("下单及时"))
1100					.findAny();
1101				IndicatorEvalSDO indicatorEvalSDO = cusOpt.get();
1102				if (cusReplace != null) {
1103					indicatorEvalSDO.setRealCompTime(cusReplace.getRealCompTime());
1104					indicatorEvalSDO.setEvaluation(cusReplace.getEvaluation());
1105				}
1106				tempCus.add(indicatorEvalSDO);
