109		public void calculatingPlaceOrderIndicator(Long projectOrderId, Boolean skipFinishProject) {
110			/*
111			 * 1.查询对应的 报价单信息。查询报价单的时机是什么？
112			 * 2.解析分类 为品类送货方式 + 送货方。
113			 * 3.以品类送货方式进行分组 送货方进行分组。
114			 * 4.计算出项目下每个品类送货方的下单考核时间。
115			 * 	这个里面包含如何底线和一城一策的考核依据是什么。这个也要落一个字段 用于展示。
116			 */
117			if (projectOrderId == null) {
118				return;
119			}
120			ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(projectOrderId);
121			if (projectOrderDto == null) {
122				return;
123			}
124			if (skipFinishProject && finishCodes.contains(projectOrderDto.getStatus())) {
125				LOGGER.info("已完成的订单, 跳过: {}", projectOrderDto.getProjectOrderId());
126				return;
127			}
128	
129			List<OrderProductDetailBo> orderProductDetailBos = null;
130			try {
131				//核心获取报价单信息
132				orderProductDetailBos = queryQuotationInfo(projectOrderDto);
133				LOGGER.info("查询到的 productDetailList 信息projectId: {} , res: {}", projectOrderDto.getProjectOrderId(), JsonUtil.obj2JsonStr(orderProductDetailBos));
134			} catch (Exception e) {
135				LOGGER.error("查询报价单信息失败", e);
136			}
137			if (CollectionUtils.isEmpty(orderProductDetailBos)) {
138				return;
139			}
140	
141			List<PlaceOrderUnique> projectUnique = findProjectUnique(projectOrderId, orderProductDetailBos);
142	
143			// 新增更新已存在订单内容
144			Integer orderMode;
145			int groupDecoration = 0;
146			int partialDecoration = 0;
147			// 进入计算流程
148			if (projectOrderDto.getControlModel().equals(1) && projectOrderDto.getBusinessModel().equals(1)) {
149				// 2.5场景
150				orderMode = OrderModeEnum.TWO_FIVE.getType();
151				String projectVersion = ProjectVersionUtil.getProjectVersionDetail(projectOrderDto);
152				if (ProjectVersionUtil.V2_5_group_whole.equals(projectVersion)
153						|| ProjectVersionUtil.V2_5_group_quan.equals(projectVersion)) {
154					// 团装标记
155					groupDecoration = 1;
156				}
157				if (ProjectVersionUtil.V2_5_partial_decoration.equals(projectVersion)) {
158					partialDecoration = 1;
159				}
160			} else if (projectOrderDto.getBusinessModel() == 2) {
161				// 如果是2.0场景需要平铺的是否需要测量以及是否通知送货场景
162				orderMode = OrderModeEnum.TWO_ZERO.getType();
163				List<PlaceOrderUnique> temp = new ArrayList<>();
164				projectUnique.forEach(item -> {
165					for (int i = 0; i <=1; i++) {
166						for (int j = 0; j <= 1; j++) {
167							PlaceOrderUnique placeOrderUnique = new PlaceOrderUnique();
168							placeOrderUnique.setCategoryId(item.getCategoryId());
169							placeOrderUnique.setCategoryName(item.getCategoryName());
170							placeOrderUnique.setDeliveryId(item.getDeliveryId());
171							placeOrderUnique.setDeliveryName(item.getDeliveryName());
172							placeOrderUnique.setDeliveryType(item.getDeliveryType());
173							placeOrderUnique.setNeedMeasure((byte) i);
174							placeOrderUnique.setHasDeliveryTask((byte) j);
175							temp.add(placeOrderUnique);
176						}
177					}
178				});
179				projectUnique = temp;
180			} else {
181				 return;
182			}
183			LOGGER.info("项目下单考核分组 {}, projectUniqu: {}", projectOrderId, JsonUtil.obj2JsonStr(projectUnique));
184			for (PlaceOrderUnique placeOrderUnique : projectUnique) {
185				IndicatorProjectOrderCreateContext context = new IndicatorProjectOrderCreateContext();
186				context.setProjectOrderDto(projectOrderDto);
187				context.setCategoryId(placeOrderUnique.getCategoryId());
188				context.setCategoryName(placeOrderUnique.getCategoryName());
189				context.setDeliveryId(placeOrderUnique.getDeliveryId());
190				context.setDeliveryName(placeOrderUnique.getDeliveryName());
191				context.setDeliveryType(placeOrderUnique.getDeliveryType());
192				context.setHasDeliveryTask(placeOrderUnique.getHasDeliveryTask());
193				context.setNeedMeasure(placeOrderUnique.getNeedMeasure());
194				context.setOrderMode(orderMode);
195				context.setGroupDecoration(groupDecoration);
196				context.setPartialDecoration(partialDecoration);
197	
198				indicatorProjectOrderService.getOrCreateProjectOrderIndicator(context);
199			}
200	
201			// 以工期变更为切入, 计算相关的考核时间
202			// 排程新配置开关
203			String projectOrderIdStr = projectOrderId.toString();
204			Boolean isInScheduleConfig;
205			try {
206				isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(projectOrderIdStr);
207			} catch (Exception e) {
208				LOGGER.info("PlaceOrderIndicatorService获取排程配置开关失败, projectOrderId:{}, err:", projectOrderIdStr, e);
209				throw new RuntimeException(e);
210			}
211	
212			// 排程初始化数据白名单
213			Boolean scheduleInit = indicatorScheduleDAGService.isScheduleProject(projectOrderIdStr);
214			if (isInScheduleConfig || scheduleInit) {
215	            try {
216					FigureScheduleParam scheduleParam = indicatorScheduleDAGService.getBaseEventsBySchedule(projectOrderIdStr, true, false, new HashSet<>());
217					if (scheduleParam != null) {
218						evalScheduleOrderService.calculateScheduleIndicatorByEvents(projectOrderIdStr, scheduleParam.getStartNodes(), null, isInScheduleConfig);
219					}
220				} catch (RpcException e) {
221					LOGGER.info("PlaceOrderIndicatorService排程考核计算失败, projectOrderId:{}, err:", projectOrderIdStr, e);
222					throw new RuntimeException(e);
223	            }
224			}
225	
226			if (!isInScheduleConfig) {
227				List<EventNode> eventNodeList = filterConstructEventNodes();
228				evalOrderService.calculateIndicatorByEvents(String.valueOf(projectOrderDto.getProjectOrderId()), eventNodeList, new ArrayList<>());
229			}
230		}
