244					unique.setDeliveryId(skuDetail.getSupplierId());
245					unique.setDeliveryName(skuDetail.getSuppliername());
246				}
247				uniques.add(unique);
248			});
249			IndicatorOrderExample indicatorOrderExample = new IndicatorOrderExample();
250			IndicatorOrderExample.Criteria criteria = indicatorOrderExample.createCriteria();
251			criteria.andProjectOrderIdEqualTo(String.valueOf(projectOrderId));
252			List<IndicatorOrder> indicatorOrders = indicatorOrderMapper.selectByExample(indicatorOrderExample);
