254				PlaceOrderUnique unique = PlaceOrderUnique.builder()
255						.categoryId(item.getCategoryId())
256						.categoryName(item.getCategoryName())
257						.deliveryType(item.getDeliveryType())
258						.deliveryId(item.getSupplierId())
259						.deliveryName(item.getDeliveryName())
260						.build();
261				uniques.add(unique);
262			});
263			IndicatorProjectOrderExample indicatorProjectOrderExample = new IndicatorProjectOrderExample();
264			indicatorProjectOrderExample.createCriteria().andProjectOrderIdEqualTo(String.valueOf(projectOrderId));
265			List<IndicatorProjectOrder> indicatorProjectOrders = indicatorProjectOrderMapper.selectByExample(indicatorProjectOrderExample);
266			indicatorProjectOrders.forEach(item -> {
267				PlaceOrderUnique unique = PlaceOrderUnique.builder()
268						.categoryId(item.getCategoryId())
269						.categoryName(item.getCategoryName())
270						.deliveryType(item.getDeliveryType())
271						.deliveryId(item.getDeliveryId())
272						.deliveryName(item.getDeliveryName())
