324						.filter(e -> Objects.nonNull(e.getSkuDetail()))
325						.filter(e -> !ignoreProductSkuTypeList.contains(e.getSkuDetail().getSkuType()))
326						.filter(e -> !ignoreQuoteSkuTypeList.contains(e.getSkuType()))
327						.collect(Collectors.toList());
328				replaceCombinedSubSku(productDetailList);
329				return productDetailList;
330			}
331			LOGGER.info("projectId :{} ,productList: {}", projectOrderDto.getProjectOrderId(), JsonUtil.obj2JsonStr(productList));
332			return productList;
333		}
