345		private void replaceCombinedSubSku(List<OrderProductDetailBo> productList, Map<String,
346			List<SkuInfoForAddMaterialSubentryDto>> combinedSkuMap){
347			if (CollectionUtils.isEmpty(productList)) {
348				return;
349			}
350			List<OrderProductDetailBo> combinedSubProductList = Lists.newArrayList();
351			Iterator<OrderProductDetailBo> iterator = productList.iterator();
352			while (iterator.hasNext()) {
353				OrderProductDetailBo product = iterator.next();
354				if (Objects.isNull(product.getSkuDetail())) {
355					continue;
356				}
357				if (!Objects.equals(product.getSkuDetail().getSkuType(), (int) com.ke.utopia.scm.product.base.constant.SkuTypeEnum.COMBINED.getType())) {
358					continue;
359				}
360				List<SkuInfoForAddMaterialSubentryDto> subSkuList = combinedSkuMap.getOrDefault(getKeyMulti(product.getSkuDetail().getMerchantId(), product.getSkuDetail().getSkuId()), Lists.newArrayList());
361				for (SkuInfoForAddMaterialSubentryDto subSkuInfo : subSkuList) {
362					OrderProductDetailBo combinedSubProduct = new OrderProductDetailBo();
363					BeanUtils.copyProperties(product,combinedSubProduct);
364					combinedSubProduct.setSkuDetail(subSkuInfo);
365					combinedSubProductList.add(combinedSubProduct);
366				}
367				iterator.remove();
368			}
369			productList.addAll(combinedSubProductList);
370		}
