377		public void finishPlaceOrderFinishTime(OfcFulfillmentNodePayload payloadData){
378			if(!payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.OMS_SUB_ORDER_CREATED.getCode())){
379				return;
380			}
381			IndicatorOrderBO orderBo = indicatorOrderService.getOrderBo(payloadData.getFlowMainNo());
382	
383			if (orderBo == null){
384				return;
385			}
386	
387			IndicatorProjectOrderExample indicatorProjectOrderExample = new IndicatorProjectOrderExample();
388			IndicatorProjectOrderExample.Criteria criteria = indicatorProjectOrderExample.createCriteria();
389			criteria.andNeedMeasureEqualTo(orderBo.getNeedMeasure() ? (byte)1:(byte)0);
390			criteria.andHasDeliveryTaskEqualTo(orderBo.getHasDeliveryTask() ? (byte)1:(byte)0);
391			criteria.andCategoryIdEqualTo(orderBo.getCategoryId());
392			criteria.andDeliveryIdEqualTo(String.valueOf(orderBo.getDeliveryId()));
393			criteria.andProjectOrderIdEqualTo(orderBo.getProjectOrderId());
394			criteria.andIsDeleteEqualTo((byte)0);
395	
396	
397			List<IndicatorProjectOrder> indicatorProjectOrders = indicatorProjectOrderMapper.selectByExample(indicatorProjectOrderExample);
398			if(CollectionUtils.isEmpty(indicatorProjectOrders)){
399				return;
400			}
401	
402			List<IndicatorProjectOrder> updateList = new ArrayList<>();
403	
404			for (IndicatorProjectOrder indicatorProjectOrder : indicatorProjectOrders) {
405				if(!indicatorProjectOrder.getFinishTime().equals(new Date(1000))){
406					return;
407				}
408				IndicatorProjectOrder temp = new IndicatorProjectOrder();
409				temp.setId(indicatorProjectOrder.getId());
410				temp.setFinishTime(orderBo.getOrderCreateTime());
411				updateList.add(temp);
412			}
413	
414			if (CollectionUtils.isNotEmpty(updateList)) {
415				for (IndicatorProjectOrder ul :updateList) {
416					indicatorProjectOrderMapper.updateByPrimaryKeySelective(ul);
417				}
418			}
419	
420		}
