292		public void doReplenishTask(OfcFulfillmentNodePayload payloadData, SubOrderComplexDto subOrderComplexDto) {
293			if (!(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(subOrderComplexDto.getSecondType())
294					&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
295					&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode()))) {
296				return;
297			}
298	
299			// 是否一品多商
300			boolean multiSupplier = StringUtils.isNotEmpty(subOrderComplexDto.getTag()) && subOrderComplexDto.getTag().contains(OrderTagEnum.DELIVERY_PRE_ALLOCATE.getCode());
301	
302			// 非一品多商，需要完成图纸上传
303			if (!multiSupplier && payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.COE_PLATFORM_UPLOAD_DRAWING.getCode())) {
304				String replenishOrderNo = payloadData.getFlowMainNo();
305	
306				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
307				fulfillmentTaskExample.createCriteria()
308						.andProjectCodeEqualTo(subOrderComplexDto.getProjectCode())
309						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.UPLOAD_DRAWINGS.getTypeCode())
310						.andRelateSubOrderNoEqualTo(replenishOrderNo)
311						.andStatusEqualTo(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())
312						.andReplenishmentEqualTo(FlowTypeEnum.REVERSE_ORDER.getCode())
313						.andIsDeleteEqualTo((byte) 0);
314	
315				// 获取上传人信息
316				List<DispatchReceiveDto> dispatchReceiveDtos = new ArrayList<>();
317				try {
318					dispatchReceiveDtos = ofcRpc.queryDispatchReceiveByMainFlowNo(replenishOrderNo);
319				} catch (Exception e) {
320					LOGGER.error("返补单拉取ofc轨迹异常, orderNo:{}, err:", replenishOrderNo, e);
321				}
322				DispatchReceiveDto updateDrawing = dispatchReceiveDtos.stream()
323						.filter(o -> o.getActionType().equals(DispatchReceiveActionTypeEnum.COE_PLATFORM_UPLOAD_DRAWING.getCode()))
324						.findFirst()
325						.orElse(null);
326	
327				TaskOperationContext context = new TaskOperationContext();
328				context.setNote("图纸上传完成");
329				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
330				if (updateDrawing != null) {
331					context.setOperationTime(updateDrawing.getOperationTime());
332					context.setUcid(StringUtils.isNotEmpty(updateDrawing.getOperatorId()) ? Long.parseLong(updateDrawing.getOperatorId()) : -1L);
333					context.setName(updateDrawing.getOperator());
334				}
335				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
336			}
337	
338			// 非一品多商，需要完成下单任务
339			if (!multiSupplier && payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.COE_PLATFORM_UPLOAD_DRAWING.getCode())) {
340				String replenishOrderNo = payloadData.getFlowMainNo();
341	
342				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
343				fulfillmentTaskExample.createCriteria()
344						.andProjectCodeEqualTo(subOrderComplexDto.getProjectCode())
345						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
346						.andRelateSubOrderNoEqualTo(replenishOrderNo)
347						.andReplenishmentEqualTo(FlowTypeEnum.REVERSE_ORDER.getCode())
348						.andStatusEqualTo(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())
349						.andIsDeleteEqualTo((byte) 0);
350	
351				TaskOperationContext context = new TaskOperationContext();
352				context.setOperationTime(new Date());
353				context.setNote("下单任务完成");
354				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
355	
356				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
357			}
358	
359			// 创建 & 完成推单（目前只用于返补单）
360			// 同一货单, OMS_NOTIFY_PUSH_WMS / OMS_NOTIFY_PUSH_SDM 消息只会发送一个, 不会都发
361			if (payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.OMS_NOTIFY_PUSH_WMS.getCode())
362					|| payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.OMS_NOTIFY_PUSH_SDM.getCode())) {
363	
364				// 获取返补单拆单信息
365				String replenishOrderNo = payloadData.getFlowMainNo();
366				SubOrderInfoDto replenishInfo;
367				try {
368					List<SubOrderInfoDto> subOrderInfoDtos = omsRpc.querySubOrderInfos(SubInfoQueryParam.builder()
369							.subOrderNos(Collections.singletonList(replenishOrderNo))
370							.withItem(true)
371							.build());
372					replenishInfo = subOrderInfoDtos.get(0);
373				} catch (RpcException e) {
374					LOGGER.error("获取返补单拆单信息失败,未查询到返补单信息，payloadData:{}, err:", JsonUtil.obj2JsonStr(payloadData), e);
375					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取返补单拆单信息失败", e);
376				}
377	
378				// 查询是否存在推单任务
379				FulfillmentTaskExample example = new FulfillmentTaskExample();
380				example.createCriteria()
381						.andRelateSubOrderNoEqualTo(replenishOrderNo)
382						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PUSH_ORDER.getTypeCode())
383						.andIsDeleteEqualTo((byte) 0);
384				FulfillmentTask pushOrderTask = fulfillmentTaskMapper.selectOneByExample(example);
385				if (pushOrderTask == null) {
386					// 创建推单任务
387					FulfillmentTaskCreateParam param = fulfillmentTaskWriteService.initReplenishTaskParam(replenishOrderNo, replenishInfo, subOrderComplexDto);
388					param.setFulfillmentTaskType(FulfillmentTaskTypeEnum.PUSH_ORDER.getTypeCode());
389					param.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
390					param.setActiveTime(replenishInfo.getCreateTime());
391					param.setReceiptOrderNo(replenishOrderNo);
392					param.setRoleType(RoleTypeEnum.SYSTEM_AUTO.getCode());
393					param.setName("系统自动");
394					param.setUcid(1000000003L);
395					pushOrderTask = fulfillmentTaskWriteService.createTask(param, false);
396				}
397	
398				// 完成推单任务
399				example.clear();
400				example.createCriteria().andIdEqualTo(pushOrderTask.getId());
401	
402				TaskOperationContext context = new TaskOperationContext();
403				context.setOperationTime(new Date());
404				context.setNote("推单任务完成");
405				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
406	
407				fulfillmentTaskWriteService.updateTask(example, context);
408	
409				// 如果下单任务未完成, 将其完成(兜底)
410				example.clear();
411				example.createCriteria()
412						.andProjectCodeEqualTo(subOrderComplexDto.getProjectCode())
413						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
414						.andRelateSubOrderNoEqualTo(replenishOrderNo)
415						.andReplenishmentEqualTo(FlowTypeEnum.REVERSE_ORDER.getCode())
416						.andStatusEqualTo(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())
417						.andIsDeleteEqualTo((byte) 0);
418				FulfillmentTask placeOrderTask = fulfillmentTaskMapper.selectOneByExample(example);
419				if (placeOrderTask != null) {
420					example.clear();
421					example.createCriteria().andIdEqualTo(placeOrderTask.getId());
422	
423					context = new TaskOperationContext();
424					context.setNote("下单任务完成(兜底)");
425					context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
426					context.setOperationTime(new Date());
427					context.setExecutingPartyNo(replenishOrderNo);
428					context.setReceiptNo(replenishOrderNo);
429					context.setRelateSubOrderNo(replenishOrderNo);
430	
431					fulfillmentTaskWriteService.updateTask(example, context);
432				}
433			}
