570		public boolean needGenerateFulfillmentTask(SubOrderComplexDto subOrderComplexDto, Boolean isInSchedule) {
571			LOGGER.info("任务生成，校验是否需要生成任务, 订单{}信息如下, fulfillmentLinkCode:{}, greyVersion:{}, orderType:{}, secondType:{}, subType:{}",
572					subOrderComplexDto.getOrderNo(), subOrderComplexDto.getFulfillmentLinkCode(),
573					subOrderComplexDto.getGreyVersion(), subOrderComplexDto.getOrderType(),
574					subOrderComplexDto.getSecondType(), subOrderComplexDto.getSubType());
575	
576			// 货物单
577			if (subOrderComplexDto.getFulfillmentLinkCode() != null && !subOrderComplexDto.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())) {
578				return false;
579			}
580	
581			// 切换到排程配置的项目, 在这里创建主材任务
582			// 因为OfcFulfillmentEventHandler后续会处理考核时间, 所以主材任务的创建要在这里完成
583			if (isInSchedule) {
584				// 处理排程货单
585				fulfillmentTaskWriteService.initTask(ScheduleInitParam.builder()
586						.orderNo(subOrderComplexDto.getOrderNo())
587						.build());
588				return false;
589			}
590	
591			// 没有重构标记理论上不生成
592			// 但是白名单欧索, 放过
593			if (!GreyVersion.OMS_REFACTOR1_0.getVersion().equals(subOrderComplexDto.getGreyVersion())
594					|| BusinessVersion.VERSION1_0.getVersion().equals(subOrderComplexDto.getBusinessVersion())) {
595				return false;
596			}
597	
598			// 理论上不生成2.5被窝(北京), 只生成全国朱雀
599			// 但是白名单欧索, 放过
600			if (BusinessVersion.VERSION2_5.getVersion().equals(subOrderComplexDto.getBusinessVersion())) {
601				try {
602					FulfillmentSystemModeConfigDto fulfillmentSystemModeConfigDto = ofcRpc.queryServiceFlowTypeConfig(subOrderComplexDto.getOrderNo());
603					if (fulfillmentSystemModeConfigDto != null
604							&& !fulfillmentSystemModeConfigDto.getSystemMode().equals(FulfillmentSystemModeEnum.ZHUQUE.name())) {
605						return false;
606					}
607				} catch (Exception e) {
608					LOGGER.error("查询订单{}2.5模式失败", subOrderComplexDto.getOrderNo(), e);
609					return false;
610				}
611			}
612	
613			// 主材和中控需要生成
614			if (subOrderComplexDto.getOrderType() != null
615					&& (OrderTypeEnum.MASTER.getType() == subOrderComplexDto.getOrderType()
616							|| OrderTypeEnum.CENTRAL.getType() == subOrderComplexDto.getOrderType())) {
617				return true;
618			}
619	
620			if (subOrderComplexDto.getSecondType() != null
621					&& (subOrderComplexDto.getSecondType() == SecondType.MASTER.getSecondType()
622							|| subOrderComplexDto.getSecondType() == SecondType.CENTRAL.getSecondType())) {
623				return true;
624			}
625	
626			// 整合零售单需要生成
627			if (subOrderComplexDto.getSecondType() != null
628					&& subOrderComplexDto.getSecondType() == SecondType.INTEGRATE_RETAIL_ORDER.getSecondType()) {
629				return true;
630			}
631	
632			// 精装全安需要生成
633			if (subOrderComplexDto.getSecondType() != null
634					&& subOrderComplexDto.getSecondType() == SecondType.JINGZHUANG_QUANAN.getSecondType()) {
635				return true;
636			}
637	
638			// 返补需要生成
639			if (subOrderComplexDto.getSecondType() != null
640					&& DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(subOrderComplexDto.getSecondType())
641					&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
642					&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode())) {
643				return true;
644			}
645	
646			return false;
647		}
