666		public List<Integer> getGenerateTaskTypeList(SubOrderComplexDto subOrderComplexDto) {
667			if (subOrderComplexDto == null) {
668				return new ArrayList<>();
669			}
670	
671			String processId = null;
672			if (StringUtils.isNotBlank(subOrderComplexDto.getProcessId())) {
673				processId = subOrderComplexDto.getProcessId();
674			}
675			if (StringUtils.isNotBlank(processId)) {
676				try {
677					List<FlowNodeDto> flowNodeDtos = ofcRpc.queryProcessAllNode(subOrderComplexDto.getOrderNo(), processId);
678					if (CollectionUtils.isEmpty(flowNodeDtos)) {
679						LOGGER.error("【接单/备货/进仓】任务生成失败，返回的流程节点为空, 订单号:{}，流程ID：{}", subOrderComplexDto.getOrderNo(), processId);
680						return new ArrayList<>();
681					}
682	
683					List<Integer> taskTypeList = new ArrayList<>();
684					for (FlowNodeDto flowNodeDto : flowNodeDtos) {
685						String nodeCode = flowNodeDto.getNodeCode();
686						if (StringUtils.isBlank(nodeCode)) {
687							continue;
688						}
689						Integer taskType = FulfillmentTaskTypeMappingEnum.getFulfillmentTaskTypeEnum(Integer.valueOf(nodeCode));
690						if (taskType != null) {
691							taskTypeList.add(taskType);
692						}
693					}
694					return taskTypeList;
695				} catch (RpcException e) {
696					LOGGER.error("【接单/备货/进仓】任务生成失败，依据流程ID未匹配到节点信息, 订单号:{}，流程ID：{},msg:{}, e:",
697							subOrderComplexDto.getOrderNo(), subOrderComplexDto.getProcessId(), e.getMessage(), e);
698				}
699			}
700			return new ArrayList<>();
701		}
